window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["24297809"]={"book":{"id":24297809,"title":"赞赏的五种语言","author":"盖瑞·查普曼","translator":"延玮","publisher":"中国商业出版社","pubdate":"2013-4","isbn":"9787504475350","tags":["心理学","赞赏","激励","心理","管理","沟通","成长","职业发展"],"memCount":5},"np":1,"pb":[12],"idx":[{"i":16363,"t":"赞赏的五种语言","l":"TF3-3","c":"鱼乐儿","g":1,"p":1},{"i":14820,"t":"如何送礼不出错","l":"TF1-1","c":"一小步","g":1,"p":1},{"i":14659,"t":"具体细节的赞美为他人赋能","l":"TF3-2","c":"Power","g":1,"p":1},{"i":10694,"t":"职场中，学会正确的赞赏","l":"TF2-4","c":"蔡抒言","g":1,"p":1},{"i":9950,"t":"帮助也是一件技术活","l":"TF2-1","c":"牛牛不想乖","g":1,"p":1},{"i":9838,"t":"表扬成就","l":"TF1-1","c":"李霞Sally","g":1,"p":1},{"i":9818,"t":"处理好人际关系最关键的一点","l":"TF1-2","c":"牛牛不想乖","g":1,"p":1},{"i":7226,"t":"站在对方角度认真倾听，理解对方感受","l":"TF1-1","c":"马宁","g":1,"p":1},{"i":4031,"t":"如何让表扬更有效","l":"TF1-1","c":"王倩倩","g":1,"p":1},{"i":4017,"t":"如何更好的赞赏人？","l":"TF1-2","c":"倪凌梅","g":1,"p":1},{"i":1894,"t":"如何赠送合适的物质性礼物 ","l":"TF1-2","c":"奔腾吧蜜蜂","g":1,"p":1},{"i":7,"t":"便签读书法练习","l":"TF1-1","c":"拆书帮小师妹","g":1,"p":1}],"ms":[{"id":16363,"topic":"赞赏的五种语言","learn_goal":"","remark":"您会赞赏他人吗？\n您如何从他人的抱怨中找到赞赏方式？\n面对看不惯的人，您又如何去赞赏他呢？","level":"TF3-3","duration":80,"status":29,"type":0,"chaishujia":{"username":"鱼乐儿","city":"常州市"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"\u003cp>【\u003cstrong>开场\u003c/strong>】\u003c/p>\u003cp>【\u003cstrong>自我介绍\u003c/strong>】\u003c/p>\u003cp>尊敬的各位师父、亲爱的拆书家们：\u003c/p>\u003cp>大家晚上好！\u003c/p>\u003cp>今天是我TF3-3的过级分享，感谢大家带着“两高”来参加活动。“气温高、热情高”。\u003c/p>\u003cp>我是鱼乐儿。我的三个标签是快乐的学习者、朗诵爱好者、三级拆书攀登者。\u003c/p>\u003cp>每次来到拆书现场很快乐，这里有一个欢乐的氛围，这里有一个环节，每次拆书家拆完都会给两个大大的苹果，吃起来很甜，这苹果是什么？是肯定，是由衷的赞美，还有一种说法叫赞赏。\u003c/p>\u003cp>当我们被赞赏时，心里是不是很愉悦？那我们去赞赏他人时他人一定是愉悦的吗？未必！为什么呢？今天就让我们一起来学习如何赞赏他人吧？一是如何从他人的抱怨中找到适合的赞赏语？另一个是如何去赞赏一个我们平时不太欣赏的人？这两个片段属于\u003cstrong>并列关系\u003c/strong>，都在想办法去赞赏他人。\u003c/p>\u003cp>【\u003cstrong>分组\u003c/strong>】为了方便学习讨论，我们先分下组。今天我们分两组：舵主、驰驰老师到唐老师这儿一组，宋老师、凌老师、到我师父这儿一组。\u003c/p>\u003cp>【\u003cstrong>目标\u003c/strong>】今天有两个学习目标：第一个拆页学完后我们会从他人的抱怨中，运用“\u003cstrong>倾听抱怨三步法\u003c/strong>”寻找到他人需要的赞赏语，在一些情景下给予合理表达，就能符合对方意愿，去建立良好关系。第二个拆页学完后，我们运用“\u003cstrong>接纳他人四步法\u003c/strong>”会在平时意见不太一致的人身上找到赞赏语，去真诚赞赏，营造快乐氛围。\u003c/p>\u003cp>【\u003cstrong>过渡语\u003c/strong>】我们先来学习第一个拆页，说个事给大家听听。\u003c/p>\u003cp>【\u003cstrong>场景介绍图书\u003c/strong>】\u003c/p>\u003cp>【\u003cstrong>事件\u003c/strong>】哎！创业艰难百事多，第一年走了十个老师。我独自坐在办公室里，寻思着哪儿出了问题。难道是我平时没有注意他们的抱怨？有的抱怨工作难度大，需要协助；有的抱怨没有和她多谈谈心，听听他们的教学思路；有的说是一起吃饭时间少了……而我只会按我的想法去赞赏他们，表扬、发红包、发奖金……\u003c/p>\u003cp>【\u003cstrong>提问\u003c/strong>】我经历了一段“黑暗料理”，原来都是抱怨惹得祸啊！我们人生中一定也少不了抱怨声，在平时和同事相处中，他们的抱怨我们是否在意、理会？我们是如何对待抱怨的呢？或者您想表达这样的赞赏方式，对方却是另外一种想法。您表扬他，他却想要礼物；您给他礼物他却想要聚餐。\u003c/p>\u003cp>【\u003cstrong>影响\u003c/strong>】我们赞赏不到点上，无法激励他们，他们也会觉得没有被重视，没有被赏识，是很有\u003cstrong>隐患\u003c/strong>的。影响人与人之间的关系，影响工作环境。如果我们在单位，或是面对领导，或是面对同事，或是面对下属，您是如何表达？如果我们在家里，我们对家人又如何表达赞赏？表达后他们的反应如何？是乐于接受还是引发冲突？适得其反，大吵一场呢？\u003c/p>\u003cp>【\u003cstrong>解决\u003c/strong>】那我们如何赞赏他人，才是适合的呢？《赞赏的五种语言》一书给了我们指导方法，或许会解决我们的困惑，让我们收获意想不到的效果。\u003c/p>\u003cp>【\u003cstrong>学习目标\u003c/strong>】第一个学习目标是：学完第一个拆页后，我们在他人的抱怨中，会运用“倾听抱怨三步法”，寻找到适合对方的赞赏语，让他们接受，促进他们更愿意完成工作，提高效率和质量。\u003c/p>\u003cp>【\u003cstrong>过渡语\u003c/strong>】为了帮助大家理解拆页，我先将赞赏语解释一下，赞赏语也叫赞赏的\u003cstrong>五种方式\u003c/strong>。他们分别是：\u003c/p>\u003cp>1、肯定的言辞。也就是用语言去表扬、赞美他人。\u003c/p>\u003cp>2、精心时刻。也就是心无旁骛在一起交流。\u003c/p>\u003cp>3、服务行为。也就是他人想获得帮助、支持。\u003c/p>\u003cp>4、称心礼物。发放奖金、礼品等。\u003c/p>\u003cp>5、身体接触。握手，击掌、拥抱等等。\u003c/p>\u003cp>每个人的需求赞赏的方式是不一样的。我喜欢精心时刻，大家也可以对照自己喜欢什么样被赞赏的方式。话不多说，看看下面拆页。\u003c/p>","ratings_count":1,"texts":[{"id":20478,"quote":"\u003cp>【\u003cstrong>过渡语\u003c/strong>】请大家花2分钟的时间，先阅读一下原文片段，看好的可以举手示意我。\u003c/p>\u003cp>《赞赏的五种语言》第96-97页\u003c/p>\u003cp>我们常常能从一个人的抱怨中发现他们的主要赞赏语是什么。布莱德是大学毕业生，刚参加工作6个月。我(盖瑞)问他:“工作怎么样?”“还行，但是似乎没有人在意我做了什么，而且总觉得我做得不够好。”我知道布莱德知道赞赏的语言，于是问道:“你的主要赞赏语是“\u003cstrong>肯定的言辞\u003c/strong>’，对吗?”他用力地点点头，说:“是的。这就是我工作不开心的原因。”我们从布莱德的抱怨中，不难听出他的主要赞赏语是什么。\u003c/p>\u003cp>如果某位员工总是抱怨同事没有时间和自己在一起，他的赞赏语很可能是“\u003cstrong>精心时刻\u003c/strong>”。如果他抱怨自己只收到一份生日礼物，他的赞赏语就有可能是“\u003cstrong>称心的礼物\u003c/strong>”。如果谁整天说没人帮自己，那么“\u003cstrong>服务的行为\u003c/strong>”就可能是他的主要赞赏语\u003c/p>\u003cp>我们的抱怨常常反映出我们情感深处所受的伤害。什么事情伤害你最深，其反面就可能是你的赞赏语。如果你接收到用这种语言说出的赞赏，伤害很可能会烟消云散。\u003c/p>","explains":"\u003cp>【\u003cstrong>过渡语\u003c/strong>】我看大家都看得差不多了，我来做进一步的讲解。\u003c/p>\u003cp>【\u003cstrong>What\u003c/strong>】这个片段给了我们一个视角，从他人的抱怨中寻找到他人想要的赞赏语，我们的赞赏才会合理。才能有效。\u003c/p>\u003cp>【\u003cstrong>Why\u003c/strong>】为什么要学习这个片段呢？我们通常会听到一些抱怨，感觉工作生活环境不自在，但没有从他们的抱怨中找到需求点，找到适合他们的赞赏点来满足他们，对他们价值或工作的充分认可。学了这个片段，我们会留心从抱怨中发现他们的需求，及时调整我们的赞赏方式，会调动他人的积极性，甚至会挽回一些损失。\u003cstrong>不这样做的坏处是\u003c/strong>：表达的赞赏语不能满足对方的想法，起不到激励作用，而且无法及时体察到对方的抱怨情况，反而会让对方不舒服。久而久之，工作氛围差离职率上升，对单位会造成严重损失。调查数据表明：12%的人因为薪资辞职，88%的人是因为工作环境、心里因素等。64%的人在单位得不到赞赏。\u003c/p>\u003cp>【\u003cstrong>概念强化讲解\u003c/strong>】\u003c/p>\u003cp>【\u003cstrong>过渡语\u003c/strong>】这个比率还是蛮高的，那我们学习这个片段就更有必要了。我们又将如何做呢？先来搞清楚这样一个概念，我从片段中提取了关键词叫“倾听抱怨”。\u003c/p>\u003cp>什么叫倾听抱怨呢？我们要细心耐心地听取抱怨。它有三个要素：一是要倾听。二是要理解。三是要有效赞赏。\u003c/p>\u003cp>举例解释一下：\u003c/p>\u003cp>【\u003cstrong>举例\u003c/strong>】李晨刚刚完成一项难度系数高的工作，为公司解决了难题。但发工资时，工资单上数字没变化。李晨抱怨道：哎！熬了多少个日夜，也不见有个奖金，只有一个空洞的表扬。还不如不挑头攻克呢？办公室同事都埋头工作，没人搭理他。\u003c/p>\u003cp>【\u003cstrong>提问\u003c/strong>】这是倾听抱怨吗？\u003c/p>\u003cp>【\u003cstrong>回答\u003c/strong>】不是。\u003c/p>\u003cp>【\u003cstrong>解析\u003c/strong>】显然说了都没人听，没人搭理。\u003c/p>\u003cp>【\u003cstrong>提问\u003c/strong>】同样的案例，李晨抱怨后，同事都过来劝他：别生气，好好工作。这是倾听抱怨吗？\u003c/p>\u003cp>【\u003cstrong>回答\u003c/strong>】不是。\u003c/p>\u003cp>【\u003cstrong>解析\u003c/strong>】只是听了，并没有人找出他抱怨的内容。\u003c/p>\u003cp>【\u003cstrong>提问\u003c/strong>】接着同事请经理过来，经理问问具体什么情况？李晨又说了一遍，经理说，我知道了，你是想要嘉奖你，发你奖金。然后走了，不了了之。这是倾听抱怨吗？\u003c/p>\u003cp>【\u003cstrong>回答\u003c/strong>】不是。\u003c/p>\u003cp>【解析】虽然听了，但没有回应。\u003c/p>\u003cp>【\u003cstrong>提问\u003c/strong>】再接下来发生什么呢？经理认真听了他的抱怨，明白了李晨的意思。他们认为通报表扬影响面更大，对他能力就是一种认可，而他本人是想要奖金啊。然后开会研究后给李晨发放了奖金。这是倾听抱怨吗？\u003c/p>\u003cp>【\u003cstrong>回答\u003c/strong>】是的。\u003c/p>\u003cp>【\u003cstrong>解析\u003c/strong>】有听、有理解、还有有效回应赞赏。倾听后找到赞赏的方式是称心的礼物——奖金。\u003c/p>\u003cp>【\u003cstrong>互动\u003c/strong>】这样讲大家明白了吧？\u003c/p>\u003cp>【\u003cstrong>回答\u003c/strong>】明白了。\u003c/p>\u003cp>【\u003cstrong>How\u003c/strong>】\u003c/p>\u003cp>【\u003cstrong>过渡语\u003c/strong>】那我们如何做到倾听抱怨呢？从抱怨中寻找到赞赏的方式，我总结为“\u003cstrong>倾听抱怨三步法\u003c/strong>”：\u003c/p>\u003cp>\u003cstrong>1、积极倾听。\u003c/strong>当我们听到他人抱怨时，我们要积极倾听，不能充耳不闻，要做出相应的反馈。因为抱怨是一种消极信号，积累多了就产生副作用。\u003c/p>\u003cp>\u003cstrong>2、理解信息。\u003c/strong>在他们的语言中我们反思一下，逆向思维，提取重要信息，他们为什么会这样说，隐藏的需求是什么？这样会找出他们的真实意图。比如“就不能和我们一起吃个饭？”其实表达的是想我们用精心时刻来赞赏。“讨厌，买什么花呢，就不知道省钱，一点也不会过日子？”说明她不想我们用买礼物的方式。“爱我你就抱抱我，爱我你就夸夸我。”虽然是一句儿歌可以听出两种赞赏语。身体的接触和赞美的言辞。\u003c/p>\u003cp>\u003cstrong>3、有效赞赏。\u003c/strong>知道他们的赞赏方式后我们对他们进行有效的赞赏，达到激励他们，认可他们价值的目的。将会收到很好效果。\u003c/p>\u003cp>这里可以细化为两步：一对照方式。看自己的赞赏方式和他们想要的有什么不同？二调整方式。用对方需求的赞赏方式进行。\u003c/p>\u003cp>【\u003cstrong>反例变正例\u003c/strong>】\u003c/p>\u003cp>回到开头的场景，学完后，我会这样运用“倾听抱怨三步法”：\u003c/p>\u003cp>\u003cstrong>1、积极倾听。\u003c/strong>平时他们在一起叽咕的时候我应该认真听听他们的想法。\u003c/p>\u003cp>\u003cstrong>2、理解信息。\u003c/strong>从他们那些抱怨中反向思考，找出他们的赞赏需求。“不能搞搞团建啊？”我听懂了，他们的赞赏语是精心时刻：我这一大堆的课件不知道什么时候做完？我明白了，他是想要服务行为赞赏语\u003c/p>\u003cp>\u003cstrong>3、有效赞赏\u003c/strong>。一对照方式。我的方式和他们需求方式的不同。我喜欢表扬、喜欢发奖金。这是肯定的言辞和称心礼物，而他们是想要精心时刻和服务行为两种方式。二调整方式。我在大家不忙的时候，可以统计一下，出去玩玩。课件做不完，可以协调安排其他老师帮忙，或者组成教研合作小组。这样一来，也就达到他们满意的赞赏，辞职的可能性会减少。\u003c/p>\u003cp>这样一来，他们高兴，我也高兴啊！原来我的“称心的礼物”一点也不称心啊！\u003c/p>\u003cp>【\u003cstrong>Where\u003c/strong>】这个片段适用于在他人付出后没有得到适当的赞赏反馈而产生抱怨时，我们从中寻求到适合对方的赞赏方式。\u003c/p>\u003cp>【\u003cstrong>预防异议\u003c/strong>】有人会说，我就喜欢某种方式，比如买礼物，他爱抱怨抱怨去，那您花钱不值得何必呢？也有人会说，如果我从对方的抱怨中听不出需求，没有意识到需要的赞赏，怎么办？可以通过其他人了解。 \u003c/p>","interaction":"\u003cp>【A2催化应用】\u003c/p>\u003cp>我们刚刚学了如何从抱怨中找到赞赏的方式，叫“\u003cstrong>倾听抱怨三步法\u003c/strong>”。好的，那么接下来我们就要尝试运用一下，看看大家掌握的情况。\u003c/p>\u003cp>请大家思考一下：在未来一个月内，您可能会遇到什么样的抱怨场景？ 请您设计一个故事，有人物、有起因、经过、结果、对话。运用“倾听抱怨三步法”解决问题，找到恰当的赞赏方式。\u003c/p>\u003cp>1、财务科里会发生什么事呢？他们在叽咕啥？2、教师办公室里，他们又抱怨什么？3、车间工人大热天，也在发牢骚啦？等等\u003c/p>\u003cp>【\u003cstrong>过渡语\u003c/strong>】给大家5分钟的时间，稍后我们请哪位老师进行公开分享，时间是3分钟。\u003c/p>\u003cp>剧本编写中……\u003c/p>\u003cp>【\u003cstrong>过渡语\u003c/strong>】编写时间差不多了。请哪位老师给我们分享一下您的小剧本。好，张老师来分享一下。时间是3分钟。\u003c/p>\u003cp>张老师分享：\u003c/p>\u003cp>暑假里我喜欢和小孩子们疯狂地玩，家里将会乱成一片。老婆下班到家一定会抱怨我们玩过没收拾家。\u003c/p>\u003cp>老婆爱整洁，每天都会把家里收拾得整整齐齐地才去工作。她到家看到这场景一定会生气。抱怨地说:我把家收拾得很整齐，你们一点不体谅我的辛苦，也不知道夸夸我、帮帮我，反而带着孩子把家里搞得乱烘烘的。\u003c/p>\u003cp>学了“倾听抱怨三步法”，我会\u003cstrong>积极倾听\u003c/strong>，不生气，也不和她争执。我从她的抱怨中\u003cstrong>理解她信息\u003c/strong>，听出了她喜欢的赞赏语是赞美的言辞，需要我肯定她赞美她。而且需要我的帮助，也就是服务的行为。\u003c/p>\u003cp>\u003cstrong>有效赞赏：\u003c/strong>我会对她说：老婆，你辛苦了！谢谢你每天都把家收拾得很整洁，我们一家住着很舒心。每次带孩子玩过我一定帮你收复原样。好吧！\u003c/p>\u003cp>老婆一听，肯定会很开心的。\u003c/p>\u003cp>【\u003cstrong>回应与反馈\u003c/strong>】在张老师分享的故事中，运用了“倾听抱怨三步法”，赞赏语满足了老婆的需求。我们用掌声感谢他的精彩分享。 \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":20479,"quote":"\u003cp>【\u003cstrong>目标2\u003c/strong>】我们学完了第一个拆页，下面我们接着学习第二个拆页。学完第二个拆页我们会对于“看不惯”，也就是意见向左人可以找到赞赏他的方法。二者是并列关系。\u003c/p>\u003cp>【\u003cstrong>过渡语\u003c/strong>】我们先来做个量表。看看我们如何赞赏“看不惯的人”？这个词是原文片段里的，我们暂且照搬使用一下。指的是有些行为方式或偏好不同，或意见相左，或差异化较大的一些人。请大家花1分钟的时间，模拟一位，化名，根据内容思考一下填写，从完全不符合1分到完全符合5分依次打分，最后看得分情况。\u003c/p>\u003cp>\u003cstrong>【过渡语】\u003c/strong>看大家都填写好了，得分如何，我们来分析一下。这个量表检测的是大家如何对待身边看不惯的人，如何找到他们的闪光点，从而认可并赞赏他们。看看得分情况，我来解读一下：\u003c/p>\u003cp>得分在20分以上的有吗？\u003c/p>\u003cp>有，说明我们态度很好，即使不欣赏他人相处没问题，为您的大度点赞。\u003c/p>\u003cp>得分在10-20分的有吗？\u003c/p>\u003cp>有，说明我们态度还不错，能够接纳他人，一起相处。最起码不会感觉不自在。\u003c/p>\u003cp>得分在10分以下，也没关系的，那我们可以考虑改变一下对他人的态度，下面的拆页可能会帮助到您。 \u003c/p>\u003cp>【\u003cstrong>过渡语\u003c/strong>】下面请大家花2分钟的时间，阅读一下原文片段，看好的伙伴可以举手示意我。\u003c/p>\u003cp>《赞赏的五种语言》第171页\u003c/p>\u003cp>第二个妨碍我们赞赏别人的原因是，对方总惹我们不高兴。我们对某些人不满，不是因为他们工作不努力，而是因为性格差异。有些人太能说了，我们看不惯;有些人太沉闷了，我们看不惯;有些人的桌上总是杂乱无章，或经常迟到，我们看不惯;甚至有些人整日乐呵呵的，我们也看不惯。\u003c/p>\u003cp>你对有些人不满，可能是因为你看不惯他们的做事方法。的确，有些人的做事方法和我们简直是南辕北辙。也许你最看不惯的是:有人居然一边工作一边听音乐，怎么能这么不专心!也许有些人的穿着打扮让你看不惯，以你的眼光，他们的着装很不得体。还有些人的生活方式和你的不样。你无法理解他们为什么要带戴鼻环，为什么文身，为他么一头乱发。年龄上的代沟也会让我们不满。中年的单亲好妈最反感那些年轻的、自以为是的小伙子。\u003c/p>\u003cp>在人际关系中，有许多使人产生矛盾的因素，这是很正常的。人和人本来就不一样。但是在工作场合，我们首先要考虑的是:“他们的工作令人满意吗?”如果他们的工作令人满意，即使你不喜欢那个人，也是可以真诚赞赏他们的;否则，如果你是主管，首先要解决他们工作上的问题。\u003c/p>\u003cp>实际上，我们永远无法改变别人的性格特征和生活方式，不可能每个人都和我们一样。我们需要学会接纳别人的不同之处，学会鼓励那些工作认真但有些行为让我们看不惯的人。\u003c/p>","explains":"\u003cp>【\u003cstrong>互动\u003c/strong>】\u003c/p>\u003cp>【\u003cstrong>提问\u003c/strong>】在单位，遇到过不喜欢的同事吗？或者说身边有看不惯的人吗？\u003c/p>\u003cp>【\u003cstrong>回答\u003c/strong>】有，没有。\u003c/p>\u003cp>【\u003cstrong>回应\u003c/strong>】我们这里都是佛系的人，大多数还是看得惯的。\u003c/p>\u003cp>【\u003cstrong>提问\u003c/strong>】有人说看不惯别人，都是自己修养不够，认同这句话吗？\u003c/p>\u003cp>【\u003cstrong>回答\u003c/strong>】同意、不同意。\u003c/p>\u003cp>【\u003cstrong>回应\u003c/strong>】有人认同，有人不认同。\u003c/p>\u003cp>【\u003cstrong>提问\u003c/strong>】工作中如果遇到性格和为人处事方式不同的人，但是我们又无法回避，怎么办？\u003c/p>\u003cp>【\u003cstrong>回答\u003c/strong>】想办法忍，和谐相处呗。\u003c/p>\u003cp>【\u003cstrong>回应\u003c/strong>】忍总不是个办法，忍不住会爆。还是要和谐相处的。如何处？赞赏他。对吧？如何赞赏？看看这个拆页是不是有答案呢？\u003c/p>\u003cp>【\u003cstrong>What\u003c/strong>】这个拆页讲的是我们总会遇到工作表现、行事方式、个性特征和我们期待的有差异的人，我们该如何去赞赏他们。\u003c/p>\u003cp>【\u003cstrong>Why\u003c/strong>】为什么要学习这个片段？因为我们身边如果遇到一些不如意的人，我们可能会忽略对他们的赞赏，用一种思维定势的方式给他们贴标签，对他们会产生消极影响，是不利于团队发展的。学完这个片段我们会关注这类人群，找寻途径，对他们进行真诚的赞赏，调动他们的积极性，营造良好的工作氛围。不这样做的坏处是：挫伤他们的积极性，整个环境会变得糟糕，影响团队运作及至整个工作的开展和进程。\u003c/p>\u003cp>【\u003cstrong>How】\u003c/strong>那我们该如何做呢？根据原文内容，我思考一下叫“接纳他人四步法”：\u003c/p>\u003cp> \u003cstrong>1、反观自己。\u003c/strong>先反观自己，是不是自己的视角错误，允许别人做别人，是不是自己戴了有色眼镜看人了，我们的观点就是标准答案吗？从看山不是山转变为看山还是山。\u003c/p>\u003cp>\u003cstrong>2、接纳对方\u003c/strong>。从三个方面来考虑，或是性格差异、或是行事方式、或是矛盾因素上来理解对方，接纳对方。\u003c/p>\u003cp>\u003cstrong>3、深入了解。\u003c/strong>当我们接纳对方之后，我们不会纠结或在意原来那些问题上，反而把看问题放在了解他的业绩上或其它方面，寻找适合他喜欢的赞赏方式上了。\u003c/p>\u003cp>\u003cstrong>4、积极赞赏。\u003c/strong>发现哪方面有优点有成就，我们给予适当的赞赏。\u003c/p>\u003cp>一个健康的和谐的人文环境因我们的内心的改变而改变。\u003c/p>\u003cp>【\u003cstrong>举例\u003c/strong>】我有一个同事叫马晓蕾。喜欢唱歌，喜欢写文章。但我们几个看她不爽，不喜欢她。每次请我们去唱歌，都是一个人麦霸，五音不全还都唱着女高音的歌，《英雄赞歌》是她开场曲。每次风烟滚滚我们就想走，四面青山真是刺耳难听。真受不了，还不让其他人唱，是让我们做听众的。后来她再喊我们都不去了。有时候同事会说她文章发表了，我也没兴趣看。更不要说赞赏了。\u003c/p>\u003cp>学了这个片段，我应该对照一下反省自己。\u003c/p>\u003cp>\u003cstrong>1、反观自己\u003c/strong>。我应该找找我自己的原因，为什么要看不惯她呢？我可以改变对她的看法吗？因为唱歌，那我们可以和她约定大家一起唱才能一起玩得长啊。说好再去也行啊，不也就不会让她包场了吗？第一 次这样，第二次不就不会发生了吗？\u003c/p>\u003cp>\u003cstrong>2、接纳对方。\u003c/strong>性格没差异、也没啥矛盾，主要是做事方法上，她喜欢独乐我喜欢众乐。她作品获奖，庆祝一下，想开心狂欢就任她乐一把呗，还有她刚学唱歌，一发而不可收就由她吧，也许就是因为没把我们当外才任性的，理解了也就接纳了。\u003c/p>\u003cp>\u003cstrong>3、深入了解。\u003c/strong>我们从其它方面去了解她。她的文章发表了，一定有值得学习的地方，最近听说文章还上了人民日报呢。 \u003c/p>\u003cp>\u003cstrong>4、积极赞赏\u003c/strong>。那还是对她的成绩，给予赞赏的。看看她的文章，仔细阅读，找出学习的点，我要好好夸夸她，再和她单独聊聊。用赞美的言辞和精心时刻两种方式。\u003c/p>\u003cp>这样一来我们会改善关系的，毕竟是一个科室的不会别扭。\u003c/p>\u003cp>【\u003cstrong>Where\u003c/strong>】这个片段适用于当你对他人有偏见时，可以尝试改变自己的想法去寻找他人的亮点，可以转化关系。 \u003c/p>\u003cp>【\u003cstrong>预防异议\u003c/strong>】有人会说看不惯就是看不惯，那能转变得了啊？是的，改变是有难度的，但如果是天天在一起的同事，别扭着不是更难吗？影响自己心情的。也有人会说赞赏一下就管用吗？人的心理变数是很大的，有时候就是一句话、一个礼物一次谈话就能改变心境发生神奇的效果或者经常赞赏，形成好习惯。心念一变万事皆变。也有人会说我改变可能对方还不习惯了，还以为我有什么阴谋呢？真诚在前，先改变自己再说，对方如何想是他的事。目的是先让自己舒服起来，主动把关系调整好。也有人会说，那我就不认同，无法理解怎么办呢？您有保留意见的权利，只要不影响工作，不影响自己的心情就好。 \u003c/p>","interaction":"\u003cp>【\u003cstrong>微行动环节\u003c/strong>】\u003c/p>\u003cp>在我们学习了“\u003cstrong>接纳他人四步法\u003c/strong>”之后，接下来我们将进入实战环节，微行动学习。这个环节将有\u003cstrong>五\u003c/strong>个步骤：\u003c/p>\u003cp>\u003cstrong>1、明确问题。2、挖掘问题本质。3、明确问题本质。4、探讨解决方案。5、分享讨论成果。\u003c/strong>\u003c/p>\u003cp>【\u003cstrong>互动提问\u003c/strong>】在此之前我们先来收集一下问题，大家身边有没有遇到过难相处，意见常常相左或看不惯的人，你们之前是如何处理的，是天天唇枪舌战还是暗地较劲？是沉默不语还是仿佛路人？请大家在小组里回忆一下，遇到过什么样的人？什么样的场景？对他有哪些看法？时间是3分钟。\u003c/p>\u003cp>【\u003cstrong>提示\u003c/strong>】每小组选个组长。一组是张老师，二组是凌老师。\u003c/p>\u003cp>小组讨论中……\u003c/p>\u003cp>【\u003cstrong>过渡语\u003c/strong>】小组讨论时间差不多了，请各小组集中推选一位代表，看谁的问题有代表性，公开分享一下。\u003c/p>\u003cp>【\u003cstrong>一组王老师\u003c/strong>】我一位朋友，我赠送他价值上万元的物品给他几十元转卖了，我很生气，看他不爽，他虽然生意上也赚了钱，很得瑟，我也不赞赏他。\u003c/p>\u003cp>【\u003cstrong>二组龚老师】\u003c/strong>我们科里岁数都比较大，突然空降个小丫头领导，天天耀武扬威的，布置工作不合理，这个你来干，这个你来干，大家很看不惯她，没人赞赏她。\u003c/p>\u003cp>【\u003cstrong>明确问题\u003c/strong>】我们两个小组都派了代表分享了他们的问题，那我们再表决一下，在这两个问题中选定一个，确定我们将要讨论的问题。\u003c/p>\u003cp>\u003cstrong>【一组】\u003c/strong>选二组龚老师的，她的问题比较明显。\u003c/p>\u003cp>【\u003cstrong>二组\u003c/strong>】选我们龚老师的，她的问题比较典型。\u003c/p>\u003cp>【\u003cstrong>回应\u003c/strong>】好，那我们无异议就鼓掌通过，确定二组龚老师作为我们今天的案主，她的问题是：看不惯空降小领导无法赞赏她怎么办？\u003c/p>\u003cp>【\u003cstrong>挖掘问题本质\u003c/strong>】那这个问题的本质是什么呢？我们先请案主龚老师将问题再分享一下，让大家清楚，以便大家对你提问。\u003c/p>\u003cp>\u003cstrong>【案主重述】\u003c/strong>上两个月，领导突然宣布一个小丫头做我们部门领导，我们大家都很诧异，先是在年龄上不能接受。后来她布置工作都是很霸气，让我们强制执行，语气很生硬，我们做都不爽，对她很有看法。\u003c/p>\u003cp>【\u003cstrong>互动\u003c/strong>】案主分享完了，我们听清楚问题了吗？那我们对她进行提问，大家提问是开放式的，了解你想知道的，但不可以直接给答案、给意见。时间是3分钟。\u003c/p>\u003cp>驰驰：她是有后台吗？\u003c/p>\u003cp>案主：不知道\u003c/p>\u003cp>唐老师：她学历高吗？\u003c/p>\u003cp>案主：高。\u003c/p>\u003cp>拆书家：她有什么资格证吗？\u003c/p>\u003cp>案主：有，她持有一个我们职业里顶级的职业资格证。\u003c/p>\u003cp>拆书家：你也有吗？\u003c/p>\u003cp>案主：我没有，一般人都考不下来。\u003c/p>\u003cp>张老师：她长得漂亮吗？\u003c/p>\u003cp>案主：一般般\u003c/p>\u003cp>陈老师：对你一个人态度不好还是对所有人？\u003c/p>\u003cp>案主：对所有人。\u003c/p>\u003cp>凌老师：平时说话很严厉是吗？\u003c/p>\u003cp>案主：是，说话总是凶巴巴的。\u003c/p>\u003cp>丁老师：新官上任三把火，想给你们下马威吗？\u003c/p>\u003cp>案主:可能吧。\u003c/p>\u003cp>颜老师：她刚毕业的吗？\u003c/p>\u003cp>案主：是的。\u003c/p>\u003cp>颜老师：没有领导力，缺乏管理经验是吗？\u003c/p>\u003cp>案主：是的哟\u003c/p>\u003cp>【\u003cstrong>过渡语\u003c/strong>】我看大家提问差不多了，根据自己获得的信息在小组里再集中讨论一下这问题的本质是什么？给大家1分钟时间，然后请各小组发表一下意见。\u003c/p>\u003cp>小组讨论中……\u003c/p>\u003cp>【\u003cstrong>过渡语\u003c/strong>】好的，看大家意见差不多能确定了，我们请各小组谈一下问题的本质是什么？\u003c/p>\u003cp>【\u003cstrong>一组\u003c/strong>】我们认为问题的本质有以下几个因素：1、年轻傲气。2、行事风格过于直接。3、空降缺乏经验。4、急于树威信，反而不被尊重。我们的结论是：这个小领导无法被信服。\u003c/p>\u003cp>【\u003cstrong>二组\u003c/strong>】我们认为问题本质有以下几个因素：1、年轻领导高高在上，行政思维太强。2、没有根据大家的性格特点来分配工作。3、交流问题严重。我们的结论是：缺乏领导力。\u003c/p>\u003cp>【\u003cstrong>明确问题本质\u003c/strong>】听了大家的意见，最终我来归纳一下，问题的本质是：小领导缺乏经验，不能被信服。案主同意吗？\u003c/p>\u003cp> 【\u003cstrong>案主\u003c/strong>】同意。\u003c/p>\u003cp>【\u003cstrong>回应\u003c/strong>】其他人还有不同意见吗？没有我们掌声表示一致通过。\u003c/p>\u003cp>【\u003cstrong>过渡语\u003c/strong>】问题的本质已经确定：小领导缺乏经验，不能被信服。我们下一步要解决的目标是什么？解决到什么程度就满意了？请案主优先回答。\u003c/p>\u003cp>【\u003cstrong>案主\u003c/strong>】我只想能一起完成工作，把绩效工资拿到手。\u003c/p>\u003cp>【\u003cstrong>探讨解决方案\u003c/strong>】我们目标明确了，需要解决的程度也清晰了，那我们各小组开始讨论方案吧！大家集思广益，头脑风暴，时间是5分钟. \u003c/p>\u003cp>小组讨论中……\u003c/p>\u003cp>【\u003cstrong>互动\u003c/strong>】时间差不多了，我们请各小组将讨论的方案进行分享。\u003c/p>\u003cp>【\u003cstrong>一组\u003c/strong>】我们的方案是： \u003c/p>\u003cp>1、\u003cstrong>反观自己\u003c/strong>。自己和她还是有差距的，她有专业最高的资质，这是强项，硬核，那我没有，就是我不如她的地方，我要考证。\u003c/p>\u003cp>2、\u003cstrong>接纳他人\u003c/strong>。领导派她来，一定有他的道理，有过人之处我可能没看到。刚来作为职场老手可以用友善的态度去欢迎她。再看看她给我们带来什么？也许这样的管理让我们收入增加，对我们有利的，我又何必在意她的态度。\u003c/p>\u003cp>3、\u003cstrong>深入了解\u003c/strong>。可以深度了解她过往的经历，也许在校就做过干部，或者有什么其他特长，领导才重点培养，委以重任的。\u003c/p>\u003cp>4、\u003cstrong>积极赞赏\u003c/strong>。经常夸赞一下，外表服饰、气质等等，也可以帮助她一起完成难度高的工作，把赞赏的五种方式适当的时候用恰当的方式进行赞赏。\u003c/p>\u003cp>【\u003cstrong>过渡语\u003c/strong>】一组给我们的方案很具体，二组的方案是什么？有雷同的部分我们不再重复，有新鲜的继续补充。\u003c/p>\u003cp>【\u003cstrong>二组\u003c/strong>】我们的方案和一组差不多，赞同一组方案。把领导不能当对手，太冒险了，把领导当自己人才能安全。 \u003c/p>\u003cp>【\u003cstrong>提问\u003c/strong>】请问案主：您对大家讨论的结果满意吗？\u003c/p>\u003cp>【\u003cstrong>案主\u003c/strong>】满意。能够帮助我反观自己调整心态，去接纳她，了解她，赞赏她，从而解决我的问题，一起把工作做好，拿到自己的绩效。\u003c/p>\u003cp>【\u003cstrong>分享讨论成果\u003c/strong>】案主满意就好。我看小组讨论都很热烈，也很用心。那我们今天的讨论结果就这样定了。通过“接纳他人四步法”解决案主看不惯空降小领导的问题\u003c/p>\u003cp>【\u003cstrong>微行动结语\u003c/strong>】非常感谢大家的积极参与，集思广益，通过解决这个问题，我们对“接纳他人四步法”有了更加深入地了解和应用。改善人与人之间的关系，建立和谐的环境。\u003c/p>\u003cp>【\u003cstrong>布置作业\u003c/strong>】\u003c/p>\u003cp>我们在现场一起学习了“接纳他人四步法”，去转变我们的思想，改变对他人原来的看法，给予积极的赞赏。那我们不满足于这一个小时的学习，我们还需要进一步加深印象。给大家布置作业，您将如何运用“接纳他人四步法”，转变对一个人的看法，还是您主动去赞赏他的成绩还是您主动帮助他完成什么事？要包括时间、地点、人物、事情的起因经过结果，你们的对话等内容，一周内请将您的反馈微信上发我。\u003c/p>\u003cp>以下是颜老师发来的反馈：\u003c/p>\u003cp>公司生产部门的有个车间主任林主任，嗓门大，一沟通工作就扯着嗓子叫，不听人说只顾自己表达意见，每次和他沟通工作都很头疼，觉得他的脾气太大了。学习了这个接纳他人四步法后，下次我在和他沟通员工培训工作时这样来做：\u003c/p>\u003cp>1、\u003cstrong>反观自己。\u003c/strong>我只是和他沟通工作，我不要受他的性格影响，只要沟通好工作就可以了。\u003c/p>\u003cp>2、\u003cstrong>接纳对方。\u003c/strong>除了嗓门大，他管理的团队很不错，生产效率高，每月都能积极地完成任务，对他的下属团队都很不错。\u003c/p>\u003cp>3、\u003cstrong>深入了解。\u003c/strong>我多和他沟通下来，了解到原来在车间里噪音大，作为管理人员不得不扯着嗓子喊才能和车间员工沟通，长期以往就习惯了。了解到这个原因才知道原来林主任的脾气大不是针对我，只是工作环境造成的，不用放在心上。\u003c/p>\u003cp>4、\u003cstrong>积极赞赏。\u003c/strong>真诚的向林主任表达赞赏，“林主任，这月的生产绩效又是完成的最好，你管理有方啊，太厉害了，要向你学习。这月我看你们车间的培训工作增加了不少，看看还有哪里需要我们工作支持的，我们多多沟通。”\u003c/p>\u003cp>非常感谢颜老师的积极配合，作业完成得很认真。\u003c/p>\u003cp> 【\u003cstrong>总结\u003c/strong>】\u003c/p>\u003cp>今天我们一起学习了两个片段，一是“\u003cstrong>倾听抱怨三步法\u003c/strong>”，在抱怨声中找到适合他人的赞赏方式；另一个片段是“\u003cstrong>接纳他人四步法\u003c/strong>”，在对有成见的人身上找到他的赞赏点，给予赞赏。两个片段看起来似乎有点负面，但是我们学过运用正确的方法可以改善我们的人际关系，建立和谐舒适的人文环境，这就是赞赏的力量！\u003c/p>\u003cp>最后用一首歌词结束我今天的分享。“如果大海能够带走我的哀愁，就象带走每条河流，所有受过的伤、所有流过的泪，我的爱，请全部带走！” 祝福大家都有大海一样的胸怀、大海一样的气魄、大海一样的深度！\u003c/p>\u003cp>今天的分享到此结束，感谢大家长时间的精心陪伴。再见啦！ \u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1691142225000,"updated_at":1691816269000,"ria":true},{"id":14820,"topic":"如何送礼不出错","learn_goal":"","remark":"，，","level":"TF1-1","duration":12,"status":30,"type":0,"chaishujia":{"username":"一小步","city":"郑州市"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"\u003cp>\u003cstrong>自我介绍\u003c/strong>\u003c/p>\u003cp>爱学习的小伙伴们，平安。很开心能和大家一起在线上拆书学习。我是来自郑州轩辕分舵的飞飞。\u003c/p>\u003cp>三个标签认识我：\u003c/p>\u003cul>\u003cli>\u003cstrong>第一个标签：全职妈妈\u003c/strong>\u003c/li>\u003c/ul>\u003cp>我喜爱读书，并用书陪伴、滋养两个孩子成长。\u003c/p>\u003cul>\u003cli>\u003cstrong>第二个标签：家庭教育讲师\u003c/strong>\u003c/li>\u003c/ul>\u003cp>我也是一位以书为媒介来做服务的家庭教育讲师。十几年来，专注陪伴各个年龄阶段的人们花样开展读书活动。\u003c/p>\u003cul>\u003cli>\u003cstrong>第三个标签：新手拆书家\u003c/strong>\u003c/li>\u003c/ul>\u003cp>如今，我是一名新手拆书家。目前虽是青铜一枚，但我很好奇我会如何在拆书帮书写自己的王者生涯。\u003c/p>\u003cp>\u003cstrong>拆书帮介绍 \u003c/strong>\u003c/p>\u003cp>接下来，我们再来认识一下拆书帮。我和拆书帮的认识呢，可以说是始于一见钟情……\u003c/p>\u003cp>在阅卷无数却仍有「读书无用」的想法时，我翻开了《这样读书就够了》这本书。瞬间就爱上了帅气的「拆书法」。\u003c/p>\u003cp>\u003cstrong>拆书法\u003c/strong>\u003c/p>\u003cp>「拆书法」是一种强调「以学习者为中心」而不是以知识为中心的学习方法论。在我们感觉读了很多书却不会用的时候，拆书法可以让我们拥有将书中知识转化为解决实际问题的能力。\u003c/p>\u003cp>它分为两种：\u003c/p>\u003cp>一种是供个人学习的RIA便签法：R是原文阅读，I是用自己的语言解读诠释，A是应用。\u003c/p>\u003cp>另一种是供组织学习的RIA现场学习法：也就是由一位拆书家通过拆书法组织一场学习培训课，引导促进一群人的学习。\u003c/p>\u003cp>\u003cstrong>拆书帮\u003c/strong>\u003c/p>\u003cp>「拆书帮」是「拆书法」学习爱好者社群。它是非营利青年自组织，各地都有它的分舵。透过深度陪伴、彼此赋能的方式帮助人们提升学习力并持续精进，成为使这个世界变得更好的「拆书家」。\u003c/p>\u003cp>我预感，我和拆书帮不仅始于一见钟情，且要终于相守相伴……\u003c/p>","ratings_count":1,"texts":[{"id":18842,"quote":"\u003cp>这个片段摘自《赞赏的五种语言》这本书，这本书的作者是盖瑞.查普曼博士。书中详细介绍了激励语言的理念以及在实际生活中的应用，适合所有想要改善人际关系的人们阅读。这本书也被称为另一本比较有影响力的书籍《爱的五种语言》的姊妹篇。\u003c/p>\u003cp>\u003cstrong>主题：如何送礼不出错？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>出自《赞赏的五种语言》P056--057\u003c/strong>\u003c/p>\u003cp>内容如下：\u003c/p>\u003cp>\u003cstrong>「礼物：送给谁，送什么」\u003c/strong>\u003c/p>\u003cp>要想让那个礼物起到鼓励的作用，要注意两个关键点：\u003c/p>\u003cp>\u003cstrong>第一，只给那些喜欢礼物的人送礼物。\u003c/strong>\u003c/p>\u003cp>如果一个人对礼物不在意的话，你最好还是用他欣赏的主要赞赏语来表达对他的赞赏。人与人不同，有些人格外看重礼物，也有人对此不屑一顾。这里我们想再次强调：如果你想让人们感到被赏识，就要说他们的主要赞赏语。即使是赠送礼物，你也要注意，赠送的礼物要让他们觉得有意义。\u003c/p>\u003cp>例如圣诞节时，你给所有员工买礼物，人手一份。有人非常高兴，有人反映平平，有些人甚至觉得礼物没用，扭头就给了别人。看到这一幕，你肯定觉得自己简直是在浪费时间和金钱。最好的办法是，送礼之前先了解一下，哪些人的主要或第二赞赏语是“称心的礼物”，然后再为他们选择合适的礼物。\u003c/p>\u003cp>第二，选择让对方觉得有价值的礼物。\u003c/p>\u003cp>如果你送给某位男士两张芭蕾舞票，他不会觉得温暖又舒心。同样，单单想一想在寒冷的周日下午坐在球场上看职业橄榄球赛，女士们就会觉得浑身发冷。如果你把芭蕾舞演出门票给某位喜欢芭蕾舞的员工，这会让他们难以忘怀。橄榄球票也是同样道理。如果你是管理者，可能会说：“这难度也太大了，我可不想把时间浪费在送礼上。干脆什么都不送。”这种想法可以理解，但这种一刀切的处理方式，会让很多喜欢礼物的人感觉不到被欣赏。\u003c/p>","explains":"\u003cp>中国自古被称为“礼仪之邦”，送礼文化也源远流长，古人说“礼尚往来，来而不往非礼也“。\u003c/p>\u003cp>这种表达感谢和关爱的方式到如今仍被大家所重视。\u003c/p>\u003cp>有一种期待叫做：所有的节日都可以成为收礼物的日子\u003c/p>\u003cp>有一种恐惧叫做：过节不送礼，会不会「作死」？\u003c/p>\u003cp>有一种难过叫做：我一切的创意在你眼里都是土气\u003c/p>\u003cp>有一种大写的服气叫做：中科大博士写20万字论文谈「如何给女朋友送礼物」\u003c/p>\u003cp>「礼物」，顾名思义是「礼+物」。\u003c/p>\u003cp>如何透过一个物质礼物，能恰到好处表达自己的情感和心意。是需要通过学习，掌握合适方法的一件事情。\u003c/p>\u003cp>\u003cstrong>What\u003c/strong>\u003c/p>\u003cp>今天这个片段分享的是【如何送礼不会错」可以使用的方法，使用这个方法能够使我们在送礼物时既能表明心意，也能建立彼此的亲密关系。\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>\u003c/p>\u003cp>我们在送礼物时，常会遇到不知道对方喜不喜欢收礼物？也不知道送给对方什么样的礼物才更合适？有时候送出礼物后，没觉得对方有什么特别明显的反应。也有时候会因为送错礼物而招致反感。\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>\u003c/p>\u003cp>在送礼物的时候可以这样做：\u003c/p>\u003cp>\u003cstrong>第一\u003c/strong> \u003cstrong>探一探对方是否喜欢礼物\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1. 观察或询问对方是否喜欢礼物\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2. 借用测评工具了解对方是否喜欢礼物\u003c/strong>\u003c/p>\u003cp>在《赞赏的五种语言》一书中就特别在附录部分放了测评工具供人们使用。\u003c/p>\u003cp>以上的方法我们可以任选一种使用。\u003c/p>\u003cp>确定对方喜欢收礼物，再去考虑送什么礼物合适？如果不喜欢，我们就不首选送礼物这个方式。\u003c/p>\u003cp>\u003cstrong>第二\u003c/strong> \u003cstrong>查一查对方喜欢什么礼物\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.让对方列出想要的礼物清单，选择其中的一样送给对方。\u003c/strong>\u003c/p>\u003cp>例如，邀请对方写出生日时最想收到的五个礼物，根据自己的实际能力选择其中一样送给对方。\u003c/p>\u003cp>\u003cstrong>2.自己列出一份礼物清单，让对方从中选出最喜欢的一个作为礼物。\u003c/strong>\u003c/p>\u003cp>根据对对方的观察列出一份你想要送出的礼物清单，让对方从中选择最喜欢的一个作为礼物。\u003c/p>\u003cp>\u003cstrong>Where\u003c/strong>\u003c/p>\u003cp>这种方法适用于想要借着送礼物来表达情意、增进亲密的任何人际关系。亲人、朋友、师生、职场等都可以使用。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1\u003c/strong>\u003c/p>\u003cp>\u003cstrong>事件\u003c/strong>\u003c/p>\u003cp>提到送礼物，收礼物。我想到了刚加入郑州轩辕分舵时的一段美好经历。\u003c/p>\u003cp>拜师礼时要求师徒要互赠礼物，当时我和师父刚认识不久，对彼此还不是特别的熟悉。因为疫情封控我们也无法见面，快递也不通。就在拜师礼前几天，师父发给我一份线上礼物清单，让我自己从里面选出一份最中意的作为礼物。清单中有三个选项，分别对准了娱乐、休息、学习三种需要。这份清单的每一项都戳中了我的小爱好。最后我在每项都很喜欢的清单中选了一个自己最中意的。\u003c/p>\u003cp>\u003cstrong>反思\u003c/strong>\u003c/p>\u003cp>当拜师礼要求我们需要做送礼物这件事的时候，师父根据平日里我们的沟通，透过微信朋友圈的观察，划定了我喜好的范围。也让我从一份清单中选择自己喜爱的礼物。这样的做法让我感受到了她的用心，也瞬间拉近了我们之间的关系。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003c/p>\u003cp>\u003cstrong>目标\u003c/strong>\u003c/p>\u003cp>用今天所学习的方法在圣诞节给工作室的3名志愿者送礼物\u003c/p>\u003cp>\u003cstrong>行动\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1. 探一探对方是否喜欢礼物\u003c/strong>\u003c/p>\u003cp>在12月第一周，私下通过测评工具探问3名志愿者是否喜欢礼物。对于礼物排序比较靠前的人们选择用送礼物的方式。对于不喜欢甚至排斥礼物的人们则放弃这种方式。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> \u003cstrong>查一查对方喜欢什么礼物\u003c/strong>\u003c/p>\u003cp>在12月第二周，通过日常对志愿者的观察和了解，也在工作室要求的金额限度下列一份清单让对方从中选择最中意的一个作为礼物。\u003c/p>\u003cp>\u003cstrong>总\u003c/strong> \u003cstrong>结\u003c/strong>\u003c/p>\u003cp>最后我们总结一下今天的拆书。如何在送礼时不出错呢？我们可以这样做：\u003c/p>\u003cp>\u003cstrong>第一，探一探对方是否喜欢礼物\u003c/strong>\u003c/p>\u003cp>我们可以透过观察、询问、或借用测评工具了解对方是否喜欢礼物。\u003c/p>\u003cp>\u003cstrong>第二，查一查对方喜欢什么礼物\u003c/strong>\u003c/p>\u003cp>1. 让对方列出想要的礼物清单，选择其中的一样送给对方。\u003c/p>\u003cp>2. 自己列出一份礼物清单，让对方从中选出最喜欢的一个作为礼物。\u003c/p>\u003cp>使用这个方法可以让我们送出物质礼物时既能表明心意，也能增进彼此的亲密关系。\u003c/p>\u003cp>今天的分享就到此结束了，希望这个片段给各位小伙伴在送礼物时带去帮助。感恩你的聆听和陪伴。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1670847897000,"updated_at":1671029101000,"ria":true},{"id":14659,"topic":"具体细节的赞美为他人赋能","learn_goal":"","remark":"赞美的五种语言-具体细节的赞美为他人赋能，增进关系和谐-江丫丫","level":"TF3-2","duration":13,"status":30,"type":0,"chaishujia":{"username":"Power","city":"成都市"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"\u003cp>自我介绍\u003c/p>\u003cp>1分钟\u003c/p>\u003cp>各位伙伴们大家晚上好，我是Power,能量的意思。我希望自己是一个充满能量的人。当然，大家也可以叫我巧巧。因为我的名字叫彭巧巧。\u003c/p>\u003cp>我喜欢热闹，也喜欢独处。\u003c/p>\u003cp>人多的时候我愿意担任那个活跃气氛的角色。\u003c/p>\u003cp>独处的时候也无比享受一个人的时光。\u003c/p>\u003cp>我喜欢一个人在深山老林看书和思考。\u003c/p>\u003cp>也喜欢和爱学习的伙伴一起交流探讨。\u003c/p>\u003cp>所以我来到了拆书帮。今天是我3-2的晋级。\u003c/p>\u003cp>因为之后的分享会涉及到讨论环节，所以我们现在进行一个分组。\u003c/p>\u003cp>图书介绍\u003c/p>\u003cp>2分钟\u003c/p>\u003cp>【场景介绍法】\u003c/p>\u003cp>今天为大家带来的这本书叫《赞赏的五种语言》。\u003c/p>\u003cp>【事件】\u003c/p>\u003cp>假设在工作当中，你突破了重重难关想尽了一切办法，完成了一件领导布置下来的任务，并且完成的非常漂亮，甚至创下了历史记录。但汇报给领导时，领导只是看了看数据报表，对你说了句“干得不错”。\u003c/p>\u003cp>【提问】\u003c/p>\u003cp>这个时候你有什么感受？会不会感到有一些失望？会不会怀疑自己做出的结果没有太大的价值？\u003c/p>\u003cp>【影响】\u003c/p>\u003cp>是的，假如一个人的努力和付出没有被真正的看见，获得更高的成就以后只是得到一些宽泛的称赞，比如你好棒，干得不错等，那不仅浪费了一次为对方赋能的机会，还会让对方觉得自己的价值没有被肯定，这样的赞美也不走心，可能会导致下属或者我们的孩子降低继续挑战的意愿了。\u003c/p>\u003cp>【解决】\u003c/p>\u003cp>那怎么样的赞美能够打动对方，激励到对方，为对方赋能呢？\u003c/p>\u003cp>今天带来的这本书叫做赞赏的力量，里面有很多帮助我们去赞美对方，看见对方，为对方赋能的表达方法。让每一次的赞美能最大程度的起到激励作用，增进彼此的关系，促进团队和家庭的和谐。\u003c/p>\u003cp>在正式开始今天的学习之前，先请各位先做一个自测量表，可以初步为自己赞美的能力评估一下分数。请认真阅读左边的行为描述部分，结合你平时的使用频率，在右边部分选择和你的实际情况相符的分数，在括号里画“√”，（1代表完全不符合，6代表非常符合），算出总分后请举手示意我，时间1分钟，可以开始了。\u003c/p>\u003cp>【A1自测量表】\u003c/p>\u003cp>【解析自测】\u003c/p>\u003cp>好的，大家结果基本都出来了，请问有25分以上的伙伴吗？哇哦，看来在这位伙伴的周围很幸福呢，随时都能感觉到满满的自信。\u003c/p>\u003cp>15-24分之间的伙伴有吗？非常棒，说明各位已经有了赞美他人的意识了，今天的拆页可以帮助各位进一步的让自己的赞美更有效。\u003c/p>\u003cp>有14分以下的伙伴吗？大家都很厉害啊，没有在这个分数区间的伙伴。那今天这个拆页对各位来讲就非常容易了。\u003c/p>\u003cp>学习目标\u003c/p>\u003cp>2分钟\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>（情景）在大家跟随我完成今天RIA的拆页以后，（澄清）能够在同事、爱人、孩子或有进步的时候，能通过赞美四步骤表达赞赏，肯定和认同身边的人，从而起到赋能他人和自己的作用，并在拆书现场演练一次（界定）。\u003c/p>\u003cp>那么接下来我们一起来用2分钟的时间看拆页里的一个案例，看完的伙伴可以举手示意我。\u003c/p>","ratings_count":3,"texts":[{"id":18678,"quote":"\u003cp>【\u003cstrong>R\u003c/strong>】\u003cbr>阅读原文拆页\u003c/p>\u003cp>2分钟\u003c/p>\u003cp>《赞赏的五种语言》P123\u003c/p>\u003cp>调查研究显示，员工对领导和上司的赏识，与对普通同事的赏识相比，喜欢程度是二比一。然而，我们大多数人都认为，如果能得到同事的认可，工作会更开心。为什么在工作场合中感觉被赏识如此重要呢？因为我们每个人都希望自己做的事很有价值。如果得不到上司或同事的重视，人们就会感觉自己像机器或物品那样。如果一个人努力工作却无人关注，工作积极性就会每次消失一点点。人基本的生存需要得到满足后，最迫切的就是心理需要的满足——希望被理解、被肯定、被赏识。\u003c/p>","explains":"\u003cp>&lt;I&gt;\u003c/p>\u003cp>拆书家讲解引导\u003c/p>\u003cp>5分钟\u003c/p>\u003cp>【互动提问】\u003c/p>\u003cp>各位，你觉得觉得拆页里面的关键词是什么?\u003c/p>\u003cp>学习者回复：价值\u003c/p>\u003cp>是的，价值。\u003c/p>\u003cp>那怎么样才能让人感觉到自己有价值呢？\u003c/p>\u003cp>学习者回复：被肯定，被认可，被理解的时候。\u003c/p>\u003cp>是的，在被理解，被肯定，被赏识的时候我们就会觉得自己特别有价值。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>这就是我们一起学习这个拆页的原因，通过我们具体的赞赏，能够让同事、孩子、或者爱人和父母感受到自己的价值，那么我们周围的世界就会越来越积极，越来越和谐，越来越融洽。\u003c/p>\u003cp>那么应该如何表达赞美呢？\u003c/p>\u003cp>【what】\u003c/p>\u003cp>接下来就为大家分享赞美的四个步骤。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>第一步：说事实。\u003c/p>\u003cp>比如下属在新一季度的工作中比上一季度的业绩提升了50%，这就是事实。\u003c/p>\u003cp>第二步：给评价。\u003c/p>\u003cp>说完事实以后，我们给出自己对这件事的积极评价，表达自己的肯定。\u003c/p>\u003cp>第三步：述影响。\u003c/p>\u003cp>告诉对方因为他的成果为团队带来了什么样的正向影响。\u003c/p>\u003cp>第四步：表感谢。\u003c/p>\u003cp>表达自己对对方的欣赏和感谢。\u003c/p>\u003cp>【举例说明】\u003c/p>\u003cp>用这个案例给大家举个例子。\u003c/p>\u003cp>如果我来表扬这位下属的话，按这个模型我会这样说。\u003c/p>\u003cp>1：说事实\u003c/p>\u003cp>小徐，我看到这一季度的业绩汇总报表上显示出你的业绩比上一季度的业绩提升了50%，让咱们团队整整多了30万的营业额。\u003c/p>\u003cp>2：给评价\u003c/p>\u003cp>这太赞了，我们公司还没有人做出过这样的成绩。\u003c/p>\u003cp>3：述影响\u003c/p>\u003cp>你不仅为团队做出了表率，同时也为团队的伙伴带来了希望，成为了大家的榜样。\u003c/p>\u003cp>4：表感谢\u003c/p>\u003cp>谢谢你付出的努力，为团队做出的贡献。期待你下一次更优秀的表现。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>你看，这样一来不仅对小徐的结果给予了肯定，还肯定了这个成果背后带来的附加价值，让小徐内心的荣誉感也油然而生。\u003c/p>\u003cp>当然，或许你会觉得这样的表扬太过冗长，或太过官方，不太习惯。所以在运用的时候各位需要结合当时的场景，尽可能的把语言生活化，自然的表达出来会让人感觉更真实。同时要注意，表扬的事情越具体，效果越好哦。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>这样的方法可以运用在上级对下级，家长对孩子，同事朋友之间都可。运用时或许四步不一定全部使用，有时候使前两个步骤，或者前三个步骤就能达到我们想要的效果。\u003c/p>","interaction":"\u003cp>分享【\u003cstrong>A3\u003c/strong>】便签\u003c/p>\u003cp>4-7分钟\u003c/p>\u003cp>【A3促动参与】\u003c/p>\u003cp>好了，学习了这个方法，让我们一起来练习运用一下。\u003c/p>\u003cp>接下来我会给出各位一个场景，邀请伙伴们运用今天学习到的赞美四步法设计一段对话，用刚刚讲的四个步骤对此场景进行讨论交流，最后邀请两位伙伴进行角色扮演。\u003c/p>\u003cp>场景：小李的儿子正在读初一，今天是期末考结束，公布成绩的时间。下课时小李儿子高高兴兴地拿着试卷回家，特地把卷纸放在了茶几最显眼的位置，原来这次期末考，孩子从全年级第100名提升到了年纪前50名。小李下班后回到家，看见桌上摆放的试卷心里非常喜悦。\u003c/p>\u003cp>那么如果你是小李，这个时候，你会如何运用今天学习到的赞美四步法对孩子进行表扬呢？假如你是小李的儿子。听到爸爸赞美自己，你会如何回复爸爸呢？\u003c/p>\u003cp>请大家用3分钟的时间进行讨论，讨论后请大家把讨论出来的对话简单填写在拆页上，然后我们邀请两位伙伴，一位扮演小李，一位扮演儿子，还原一下这个场景。要注意的是，两位的扮演要形成父亲和孩子的对话。而不是父亲单独的表达哦。我们开始吧。\u003c/p>\u003cp>好的，时间到啦，我们邀请2位伙伴来分享一下。\u003c/p>\u003cp>学习者行动：\u003c/p>\u003cp>学习者A扮演儿子，学习者B扮演爸爸。\u003c/p>\u003cp>学习者A说：爸爸，你有看见茶几上的水果吗？\u003c/p>\u003cp>学习者B 说：还有水果呀？哇，不仅有水果，还有宝贝的考试试卷呀。考的真不错宝贝。\u003c/p>\u003cp>学习者A说：爸爸，我这次排名还提升了呢。\u003c/p>\u003cp>学习者B说：是的，（说事实）我看到宝别的排名从全年级100名提升到了50名。（给评价）这简直太棒了。看得出来宝贝这段时间非常努力用心在读书，（述影响）爸爸因你而感到骄傲。相信妈妈看到也会很开心的。（表感谢）谢谢你宝贝，咱们家有你真好。\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>课后作业\u003c/p>\u003cp>\u003cbr>刚刚的现场练习，从二位伙伴的演练看来已经基本掌握了今天学习到的赞美的方法了。\u003c/p>\u003cp>我们在现场练习了一遍，抱着学以致用的初衷，接下来给大家布置一个课后作业。在未来的一周内，请在工作或生活中运用赞美四步法，对朋友，亲人，同事进行一个赞美。邀请大家将自己表达赞美的过程写下来，并微信反馈给我一下，让我知道这个拆页对大家是有用的，好吗。\u003c/p>\u003cp>【强有力的结尾】\u003c/p>\u003cp>好的，通过今天25分钟的学习，我们了解到人们的内心都有渴望自己有价值感，当成长或者通过自己的努力拿到成果以后，我们都希望被看见，被肯定，被赞赏。我们也知道了如何用赞美他人具体的成果或者行为，去为他人赋能，激励他人，给予他人持续前进的力量。这不仅会让各位在与他人的关系上更和谐，同时还能提升自己的领导力。\u003c/p>\u003cp>最后，祝愿各位发出自己的光，点亮自己，照亮他人。我们一起让这个世界更加美好。\u003c/p>\u003cp>好的，这就是我3-2的晋级。感谢聆听。\u003c/p>\u003cp>PS：是线上过的，没有录音，只有视频。都在百度网盘里了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1669369059000,"updated_at":1674026267000,"ria":true},{"id":10694,"topic":"职场中，学会正确的赞赏","learn_goal":"","remark":"通过“赞赏激励方式测评”得出5种赞赏的语言，能够让职场中的人了解赞赏的语言，让管理者和员工掌握赞赏语言，找到自己的需求和对应的方法，使自己获得更高的工作幸福感，提高工作效率。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"蔡抒言","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp> 大家好，我是今天的拆书家蔡抒言，很高兴有机会与大家一起拆书学习。拆书前我给大家分个组，以便于待会儿的学习，这2位小伙伴一组。\u003c/p>\u003cp>\u003cbr>【 学习目标设定 】 \u003c/p>\u003cp>赞赏是一种肯定，一种鼓励，\u003cstrong>它不仅仅是语言，其实也是行为\u003c/strong>。今天我们要通过学习“赞赏”的方法，\u003cstrong>有针对性地选择“赞赏的语言\u003c/strong>”，通过\u003cstrong>三个步骤\u003c/strong>达到\u003cstrong>打开“赞赏障碍”的心结\u003c/strong>，并能\u003cstrong>有效运用方法对不熟悉的人进行有效赞赏\u003c/strong>，达到\u003cstrong>和谐关系、促进工作的\u003c/strong>目的。\u003c/p>\u003cp>【 FAB法介绍图书 】\u003c/p>\u003cp>F：（属性）拆页内容选自《赞赏的5种语言》这本书，作者\u003cu>盖瑞·查普曼\u003c/u>、\u003cu>保罗·怀特\u003c/u>都具有\u003cstrong>专业的人际关系辅导经验\u003c/strong>，本书围绕\u003cstrong>职场中\u003c/strong>“赞赏激励项目”的调研结果，帮助职场中的人们\u003cstrong>了解\u003c/strong>什么是\u003cstrong>赞赏的语言，并能学以致用，是一本\u003c/strong>针对企业管理提供具体操作方法的\u003cstrong>指导书籍\u003c/strong>。\u003cbr> A：（作用）这本书与其他同类型图书相比，建立在\u003cstrong>案例\u003c/strong>基础上，通过“赞赏激励方式测评”得出5种赞赏的语言，能够让职场中的人\u003cstrong>了解赞赏的语言\u003c/strong>，让管理者和员工掌握\u003cstrong>赞赏语言，找到自己的需求和对应的方法，\u003c/strong>使自己获得更高的工作幸福感，提高工作效率。\u003c/p>\u003cp>B1：（全本书获益）\u003c/p>\u003cp>有时候你赞赏别人不在点上，只会笼统地说“做得不错”“真棒”等这类话，就会发现别人并不领情。因为赞赏“不走心”，让赞赏没有效果。比如，创业时，因为不了解赞赏的语言，我失去了一个得力的小伙伴，以至让项目一度停滞。不会赞赏的人让前途白废，会赞赏能让事情事半功倍，企业也能达到以情留人、控制成本的目的。\u003c/p>\u003cp>B2：很多人不习惯赞赏他人，觉得这是别人应该做的、没必要、有些做作，“\u003cstrong>心结”的障碍有时候甚至会丢掉一个合适的员工\u003c/strong>，\u003cstrong>拆页一中\u003c/strong>告诉我们，可以通过\u003cstrong>三个步骤达到打开心结\u003c/strong>，找到真诚赞赏他人，良好沟通的目的。当你\u003cstrong>遇到不熟悉的人力图进行赞赏，却找不到方法时\u003c/strong>，可以通过学习\u003cstrong>拆页二\u003c/strong>的方法——向他人求助。通过外人的帮助，指点迷津、找准方法，合理运用赞赏的语言。\u003c/p>","ratings_count":2,"texts":[{"id":14564,"quote":"\u003cp>\u003cstrong>学习目标一：当你不习惯赞赏他人时，可以尝试用三个步骤打通心结，诚意地去赞赏他人。\u003c/strong>\u003c/p>\u003cp> 摘自\u003cstrong>《赞赏的5种语言》\u003c/strong>P135\u003c/p>\u003cp>\u003cstrong>战胜“古怪因素\u003c/strong>\u003c/p>\u003cp>我们发现一些简单步骤可以减少古怪因素的影响。首先，承认这种因素的确存在。我们在帮助小组成员设计表达赞赏的行动步骤时，即使没有人提出这个问题，也会声明说：“我们发现，每次探讨这些问题的时候，大家总会觉得这种设法相互鼓励的做法有点别扭。”一旦把话说开，你会发现人们的紧张感立刻减轻了很多。\u003c/p>\u003cp>第二，我们借鉴自己以前的经验。每当人们尝试新的方法或不同的方式时，总会觉得有些古怪或别扭。万事开头难！（这样的例子不少，像学习运球、尝试新的击球方法、改变室内家具的摆放、换新发型、以及开始一项新的健身运动等。）我们鼓励大家，要理解并接受最初这种别扭的感觉，坚持下去，过不了多久，这种别扭的感觉就会消失了。\u003c/p>\u003cp>第三，还有一些实际的做法，能帮大家战胜这种最初的古怪感受。你可以在赞赏别人时用这样的开场白：“你可能会认为我这样做是因为我参加了赞赏式激励培训，但实际上……”把大家担心的事情摆在前面，通常会使这个问题淡化。还可以用些幽默的方式缓和气氛。两个接受过赞赏式激励培训的人互相鼓励时，\u003c/p>\u003cp>我们通常建议被鼓励的人这样说：“谢谢，我感觉真不错，终于有人重视我、赞赏我啦！”（说的时候要面带微笑，不能用讽刺的口吻。）当你持这种态度时，大家用到在培训中学到的各样赞赏语时就不再尴尬，而是欢声笑语一片。\u003c/p>\u003cp>最后我希望，大家在具体实施的时候，请相信他们的赞赏是真诚的。坦诚地说，接受一个新观念并在日常工作关系中应用是需要勇气的。因此，当同事愿意尝试时，我们要为此感恩：“太感谢了，至少他们还愿意尝试！”这种心态会让大家的交往更积极。在追踪培训中，我们不止一次听到人们这样说：“开始的时\u003c/p>\u003cp>候，我的确觉得这种方式很别扭，甚至有点娘娘腔。但后来，尽管知道同事说的和做的都是培训的结果，我还是感觉挺好的。我喜欢他们表达赞赏的方式。”\u003c/p>","explains":"\u003cp>【 Ｉ：拆书家讲解引导 】\u003c/p>\u003cp>\u003cstrong>\u003cu>Why:\u003c/u>\u003c/strong> 职场中，很多人觉得赞赏他人是一种很做作的行为，被赞赏的人也会觉得不真诚，因为不想做而去做，在没有做到有意识、有准备、有重点赞赏他人，很多时候就会事与愿违。\u003c/p>\u003cp>其实我就是一个不太会赞赏他人的人，因为我总觉得有些工作是很容易或者应该做好的，为这些简单能完成的事情赞赏，有点假，也容易让被赞赏的人飘。 比如，上周我们结束完一场全市的大型活动，活动按即定目标完成了。总结会上，我按惯例把工作从头到尾陈述一番，总结一段后，最后也按惯例表扬了同事小A，我是这样说的，“这次整体活动效果达到即定目标，离不开大家的辛苦付出，大家再接再励，向年终献礼!”（一般做法）事后一周，我观察了一下小A，工作还是那个样子，好像有点心事重重。事后，我得知，小A认为“这种表扬不如不说，加班加点干完，没人没钱还没补休，这意味着年底的活动，我们要做得更多，压力更大。”（不这么做的坏处）\u003c/p>\u003cp>\u003cstrong>\u003cu>What:\u003c/u>\u003c/strong> 因为我由着自己对赞赏的误解，不懂得别人的需求造成了后果，让他人产生误会，造成心理负担，继而也许会消极怠工，甚至对工作、同事和领导心生不满。所以，有效运用赞赏的语言，不仅是肯定别人，也能让自己与同事和谐相处，达到更好地推动工作，让工作氛围更好的目的。\u003c/p>\u003cp>比如如果再回到当初，运用片段中的三个步骤这么做，也许结果就会不同。\u003c/p>\u003cp>\u003cstrong>\u003cu>How：\u003c/u>第一步，意识到内心的障碍\u003c/strong>。怎么才能意识到内心障碍？从某些方面来说，当人遇到心理障碍时首先会察觉到的是自己的身体状况，比如不自觉地肌肉紧张、坐立不安，当你出现这种身体状况时其实是一种焦虑，此时非常容易发脾气、自责矛盾，这是情绪作祟，你不要受它的影响。\u003c/p>\u003cp>\u003cstrong>第二步，对抗别扭的感觉。如何对抗呢？\u003c/strong>可以给自己\u003cstrong>心理暗示\u003c/strong>：默想“如果不……这样,就会……那样”。\u003cstrong>分散注意力，\u003c/strong>不要认为“赞赏他人”是有负担的，或者担心你的赞赏别人不领情。\u003cstrong>坚定相信\u003c/strong>，用“赞赏他人”的语言。\u003c/p>\u003cp>\u003cstrong>第三步，敞开心菲\u003c/strong>，\u003cstrong>开诚布公与人沟通\u003c/strong>。比如像上次活动，我如果这样说“小A，我是一个不擅长去表达的人，对于你的付出我很感动，知道你是加班加点地，放弃了自己的休息时间，为公司的活动尽心尽职。我也希望接下去的工作，你有什么困难和需求，可以直接告诉我，我也会尽能力帮你解决，毕竟这是我们大家的事情！”赞赏真诚且具体，还主要去了解同事的需求，并表示能主动帮助他。诚意的沟通才会让别人感受到你的赞赏。（这么做的好处）（反例变正例）\u003c/p>\u003cp>\u003cstrong>\u003cu>Where: \u003c/u>\u003c/strong> 职场中，有的人因性格原因，从来不会赞赏人，从另一方面来说，这是对成就感的曲解；另外，企业文化因其固有的模式，不习惯用赞赏激励的方式来进行管理，那么我们也没有必要花费时间和精力去改变。针对这些情况时，我们也没必要刻意勉强他人。\u003c/p>\u003cp>\u003cstrong>\u003cu>预防疑义：\u003c/u>\u003c/strong> 有人说，这种赞赏是老板用来管人的工具，我们这些打工的不需要学习。其实，有效的赞赏是人际沟通中的一个重要环节，赞美声中不仅能认识到自己的存在价值,真心的赞美还会获得社会满足感，是人本能的需要。\u003c/p>\u003cp>需要关注的一个环节，在下级在对上级进行赞赏时，因身份原因，需要注意一下适度，切忌太刻意而让别人觉得你是在拍马屁。\u003c/p>","interaction":"\u003cp>【 A 学习者拆为己用 】\u003c/p>\u003cp>\u003cstrong>Ａ1：\u003c/strong>学习者经历 让我们来回忆一下，最近这一周或者这半个月里，在有没有去赞赏过他人？是怎么去赞赏的呢？请按我刚才的分组，大家在小组内讨论一下。时间是5分钟。\u003c/p>\u003cp>\u003cstrong>学习者米勒：\u003c/strong>我工作的单位，今年小组里新来的一位同事一直不合群，不好搞懂他。我有时候很想与他多一些交流，但又担心他不冷不热的态度会影响到我。就算他工作完成得不错，我也就是用“还可以！行吧！”这类比较简单通用的语言，没有刻意做其他的赞赏或者行为。这样半年过去了，发现他还是不太合群。\u003c/p>\u003cp> \u003cstrong>A1+ ：\u003c/strong>反思加工 如果回到当初，你经历这件事时，会如何做呢？下面我们请一位学习来分享一下刚才的讨论结果。\u003c/p>\u003cp>\u003cstrong>学习者米勒：\u003c/strong>今天学习到这个片段，如果回到当初，我可能会先注意一下自己是不是有异样的情绪，比如心情沉重，有压力，紧张，矛盾等；然后会尝试“不要这样”，要“用积极的心态去看对方”，再就是坦诚自己的心态，与他进行沟通。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>\u003c/p>\u003cp>非常感谢这位小伙伴的分享，他通过三步法，打破了“赞赏困难的心结”，学会了用正确的心态面对赞赏。\u003c/p>\u003cp>\u003cstrong>Ａ2：\u003c/strong>我相信大家已经慢慢领悟到其中的玄机，接下去还要通过不断练习才能加深我们对“赞赏语言”的了解。\u003c/p>\u003cp>下面让我们再练习一下，试想在接下去的一周里，你会遇到一件什么事，有哪些人，你可能要对他们进行赞赏，但你又不想去赞赏。此时，请你运用这二个步骤，化解内心的矛盾和纠结，大胆去赞赏他人吧。请大家在小组内分享一下。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":14565,"quote":"\u003cp>\u003cstrong>【拆页一与折页二过渡】\u003c/strong> 打开了赞赏的心结，这样对你在后期做赞赏激励会有很大的帮助，那么当你遇到一个不太熟悉的人，想通过赞赏拉近彼此的距离时，该通过什么方法达到这个目的呢？请看拆页二。\u003c/p>\u003cp>拆页二　　2分钟\u003c/p>\u003cp>\u003cstrong>学习目标二：当你不了解想赞赏的人时，可以借助外力（他人或者信息）的帮助，通过二个步骤进行赞赏。\u003c/strong>\u003c/p>\u003cp>摘自\u003cstrong>《赞赏的5种语言》\u003c/strong>P140-P141\u003c/p>\u003cp>有些领导人很难赞赏不同他们直接汇报的员工，因为他们不了解他的职责，这主要是由于公司内部信息沟通不畅。罗伯是一名主管，他说:“我真不知道克里斯每天都在忙什么,只是看到他一会在这里,一会又在那里。他是负责计算机的吧,怎么不待在自己办公室里呢?”\u003c/p>\u003cp>莎莎是信息部门的主管,向罗伯解释说:“克里斯是网络管理工程师。他的\u003c/p>\u003cp>首要职责是确保每个人都能顺利登录上网,发送信息没有障碍。你之所以看到他东游西逛,是因为有些人的网络出了问题,他必须到每个人的座位上去,了解情况和解决问题。他在做自己应该做的事情,而且做得很好。”\u003c/p>\u003cp>“哦,那我明白了。这太好了!”罗伯回答道,稍有些不好意思。\u003c/p>\u003cp>如果你对其他部门员工的工作产生疑问，最明智的做法就是去找到他的直接主管询问。你也许会发现你的疑问源于不了解情况。两天后,罗伯在走廊里遇见克里斯,对他说:“克里斯,我听莎莎说你工作很认真。 谢谢你为公司所付出的努力。”克里斯听到这些,感觉很受鼓励。罗伯花时间去了解事实, 他就能真诚地向克里斯表达感谢了。\u003c/p>","explains":"\u003cp>【 Ｉ：拆书家讲解引导 】\u003c/p>\u003cp>\u003cu>Why: \u003c/u>工作中，当你面对不是同一个部门的同事，面对不熟悉的人时，因为不了解情况，是很难用“赞赏的语言”打动他人，达到有效沟通的。拆页二中提到，有时候\u003cstrong>赞赏障碍来自于外部因素，\u003c/strong>比如公司结构和流程等。\u003c/p>\u003cp>\u003cu>What: \u003c/u>因为对同事的工作职责和流程并不了解，当产生置疑时，可以通过外介（对他熟悉了解的人）的帮助，主动沟通信息，适时运用“\u003cstrong>肯定的言辞、精心的时刻、服务的行为、称心的礼物、身体的接触”5种赞赏的语言，\u003c/strong>避免产生矛盾，具体可以通过以下二个步骤，不仅能化解心中的疑虑，还能进行有效赞赏沟通，促和谐关系。\u003c/p>\u003cp>\u003cu>How: \u003c/u>这里有以下二个步骤：\u003c/p>\u003cp>一、求助他人，解答置疑/困惑；向他人求助时，要找到与赞赏对象熟悉的人。比如和其同一个部门、同一个组的，和他（她）经常在一起工作的人等等，这样才能了解到真实详细的情况。注意在向他们打听信息时不要带有观点，只要就事论事，简单说明看到的情况，并且说出自己的困惑即可。\u003c/p>\u003cp>二、表达赞赏要合适。这里的表达要注意几点：（细化步骤）\u003c/p>\u003cp>①赞赏不刻意。不是直接管理/工作中接触到的员工（同事），不要特别安排赞赏的时间地点（原文里的地点是在走廊）。\u003c/p>\u003cp>②赞赏要准确。强调直接信息的来源（原文里提到到莎莎，是罗伯的直接主管），因此信息准确。\u003c/p>\u003cp>③赞赏要简单。表达简明扼要，直接将信息转换成赞赏的言语，说出自己的赞赏，让对方觉得你的真诚。\u003c/p>\u003cp>【意译案例】\u003c/p>\u003cp>我们小组有3个小伙子，都是90后，除小肖是外向型的，其余2个小伙子都不太爱讲话。对于90后的管理，我习惯按周来布置工作，希望也能给大家一些弹性时间，让大家自由发挥。有一段时间，我总是看到小肖每天上串下跳，到处晃。一下在小羊旁边一下在小彭旁边，总看他们在讲话。我担心他的工作状态会影响工作进度。于是我就私下问了一下小羊和小彭，他们告诉我，小肖因为熟悉工作流程和一些技术环节，所以他们总爱找小肖帮忙，小肖又很热情，也不会推脱，就会用自己的时间帮另2个人。\u003c/p>\u003cp>对于小肖的工作态度和帮助他人的行为我了解后，就明白他其实不是在讲闲话，也没有耽误别人的工作。于是有一次看到他在茶水间打咖啡，就凑过去，跟他聊起来，还说“你年龄最小，却最熟悉业务，还能帮助其他人，不错。值得肯定。”\u003c/p>\u003cp>【不这样做的坏处】\u003c/p>\u003cp>通常身居要职的领导们，要统领全局，需要关注的事情很多，有时候因为信息有遗漏难免会主观判断，盲目强势。比如，如果在上面这段经历中，我没有通过和小肖一组的人去了解真实情况，而去武断判断，肯定就会冤枉到一个工作热情的员工。\u003c/p>\u003cp>或者再举个更生动的例子，如果当你遇到一个年轻的女性，不明就理就说“你这么漂亮孩子肯定也蛮漂亮的。”但其实别人还没结婚，那就尴尬吧。当你想去和一个不熟悉的人拉近关系又找不到合适的赞赏话语时，可以通过她身边的人打听一下相关情况再去赞赏，这样就不会造成坏的结果。\u003c/p>\u003cp>比如像下面这个例子，我们就要引起关注：\u003c/p>\u003cp>【反面案例】\u003c/p>\u003cp> 我们也会遇到有时候身边同事或者下属确实表现欠佳时，比如平时很尽职的办公室小陈，这段时间总是卡着点上班，还经常请假。工作中的材料也总是出错，办公室李主任终于憋不住，昨天就发了飙，说了她一通，还说要再这样出错就要扣工资。\u003c/p>\u003cp>【后果】\u003c/p>\u003cp> 其实最近小陈家里出了点事，婆婆生病了，孩子还在幼儿园，老公一直在外地出差，家里没人照顾，压力特别大，精力也实在跟不上。因为主任的批评，搞得小陈很委曲，在办公室里大哭了一场，撂下东西就走人了，搞得办公室的气氛特别压抑。\u003c/p>\u003cp>【正面案例】\u003c/p>\u003cp>李主任如果能及时多找些人了解一下情况，得知小陈的困难，甚至还能想办法解决一下小陈的具体问题，比如找到熟悉的人，能接小陈孩子回家，或者公司能帮着请一个临时工，帮她家里做一个饭，照顾一下婆婆等。我想，这样的“赞赏语言”是切实地解决了小陈之需，小陈也会更加努力工作以做回报。\u003c/p>\u003cp>【异议预防】\u003c/p>\u003cp>有人说，不会所有的领导都这么民主，特别是私企的老板，他们认为自己决定的事情不用那么麻烦。其实我更想说的是，如果这位领导没有意识到领导与员工的利益关系是相辅相成的话，那么离公司关门也不远了。\u003cbr>【Where】\u003c/p>\u003cp>这种方法不适合办企业很久，而企业管理者特别专制和固执的人，因为他们会认为按自己的意愿做了这么多年也没出啥事，干嘛要改变。\u003c/p>","interaction":"\u003cp>【A3之场景设计】\u003c/p>\u003cp>下面我们来演练一个场景，试着用刚才的二步法去练习一下。场景是这样的：领导Ａ最近看到执行部的小陈总是晚到早走，于是问起小陈的主管，了解情况。得知小陈忙于公司下周活动，时间很紧，所以会来晚。得知情况后，领导Ａ找机会肯定了小陈。\u003c/p>\u003cp>【A3之小组讨论】\u003c/p>\u003cp>现在大家两人一组，一人扮演领导Ａ，一人扮演员工小陈。假如你是领导Ａ，如何运用今天学到的三步法向员工小陈正确表达有效赞赏呢？\u003c/p>\u003cp>给大家10分钟的时间，进行讨论，并且在小组里进行演练。\u003c/p>\u003cp>【A3之角色扮演】\u003c/p>\u003cp>现在我们邀请这组小伙伴来进行角色扮演。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>\u003cstrong>领导A：\u003c/strong>小陈，听说你最近特别忙，有没有需要我能提供帮助的地方吗？\u003c/p>\u003cp>\u003cstrong>小陈：\u003c/strong>领导，我最近在忙着公司的一个活动，目前都在对接物料，时间很紧，也很想为公司控制一下成本，所以总是到处跑。\u003c/p>\u003cp>\u003cstrong>领导A：\u003c/strong>是啊，我也\u003cstrong>听你的组长说\u003c/strong>，公司年底事情是特别多，很多事来得也很急，人手也不够，你辛苦了！\u003c/p>\u003cp>\u003cstrong>小陈：\u003c/strong>感谢领导的关心，非常时期我们也想尽量多做点，为公司控制点成本，大家年底才能有好的收入啊。\u003c/p>\u003cp>\u003cstrong>领导A：\u003c/strong>嗯，肯定的，有你这样的员工，我们肯定会在\u003cstrong>年底表彰上给记一功，还会发个大红包给你。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小陈：\u003c/strong>啊，太感谢领导了，我一定会努力工作。\u003c/p>\u003cp>【拆书家反馈】\u003c/p>\u003cp>你看，刚才的这段演练充分看到了大家在运用遇到“赞赏障碍”时，用到的2步法，顺情合理地把领导的困惑解除了，并还找到员工的赞赏需求点，进行了有效赞赏。\u003c/p>\u003cp>【A2之经验激活】\u003c/p>\u003cp>在下周或者近一个月的工作中，设想一下，有可能会出现的场景，与不熟悉的同事合作，想对他进行有效的赞赏。\u003c/p>\u003cp>分步催化：\u003c/p>\u003cp>拆书家：首先，你要想到最近有件什么样的事情，需要与不熟悉的人合作？想想年底，大家会经常做的某类事情。\u003c/p>\u003cp>学习者：年底活动多，考核多，报帐多，都可能会有与不熟悉的人接触。\u003c/p>\u003cp>拆书家：对的，想想这个人是谁？哪个部门？过程中会出现什么障碍？\u003c/p>\u003cp>　　给大家５分钟的时间在小组内讨论，只需要分享可能遇到的情景，不需要说具体怎么做。请2位小伙伴分享自己的情景——\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>年底我们要对一位刚来的老师做考评，但平时我与他接触不多，他们同事也和他说话不太多。通过同事的了解只能代表一部分观点，还不能全面关注到他的整体情况，考评如果不能做到全面，到时候就可能会造成不必要的误会。\u003c/p>\u003cp>【A2之催化应用】\u003c/p>\u003cp>刚才每个人都说出自己将来可能遇到的情景，现在请你想象一下，在这样的场景中，你会如何应用今天所学到的二个步骤来做呢？\u003c/p>\u003cp>\u003cstrong>学习者者反馈：\u003c/strong>让我想到，考评还可以通过学生和学长来反馈这位老师的整体工作能力和素质。通过一些问卷和谈话的方式，了解这位老师的工作情况和对工作的态度，对学生的态度，这样就更客观地能综合评判到他。也能找到他的赞赏需求，对他进行有效赞赏。\u003c/p>\u003cp>【拆书家反馈】\u003c/p>\u003cp> 是啊，你看，这位小伙伴就学到了这种方法，相信在运用的过程中，你所能收获的不仅是推动工作的完成，也能让你成为受大家欢迎的人。\u003c/p>\u003cp>【结尾】\u003c/p>\u003cp>希望通过今天的学习能够让大家体会到，\u003cstrong>喜欢听好话是人的天性，赞赏他人是一种智慧，实事求是的赞美更是一幅良方\u003c/strong>。相处是一门学问，是一生的功课。赞赏和鼓励和你一起共同工作的战友和同事。改善工作环境，从自己做起。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1606450653000,"updated_at":1606718654000,"ria":true},{"id":9950,"topic":"帮助也是一件技术活","learn_goal":"","remark":"你是否有过真诚的赞赏对方，对方却不领情，但问题出在哪里你并不清楚？是否想创造更积极的工作环境，却无从下手？这本书能指导你正确的人际交往方法，如果你想在职场中更好的为下属营造良好的工作氛围，或者掌握和同事相处的方法，都可以从这中得到一些启发和收获。\n","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"牛牛不想乖","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"\u003cp>\u003cstrong>个人介绍【16秒】\u003c/strong>\u003c/p>\u003cp>大家好我是牛牛不想乖，先自我介绍一下，我的三个标签：第一个是我的本职工作是一名电商行业的从业者，第二标签我是一名精时力的践行者，第三个便签我是一名正在跟着我师父裘叔拆书过级的小白拆书家。今天我给大家带来的拆页选自《赞赏的五种语言》\u003c/p>\u003cp>主题是：帮助也是一件技术活，\u003c/p>\u003cp>学习目标：在跟随我完成本次的RIA的现场学习之后，学习者能够使用正确提供帮助的技巧，配合同事完成工作任务。\u003c/p>\u003cp>\u003cstrong>FAB·介绍书籍【1分30秒】\u003c/strong>\u003c/p>\u003cp>F:\u003c/p>\u003cp>这本《赞赏的五种语言》作者是盖瑞查普曼和保罗怀特。盖瑞查普曼是《纽约时报》百万畅销书作者，保罗怀特是资深的心理学家。这本书主要讲了如何通过赞赏的行为，营造一个更加和谐的工作氛围，提高工作积极性。\u003c/p>\u003cp>A\u003c/p>\u003cp>《赞赏的五种语言》作为一本大众心理学入门的书籍，对职场人际交往有很多指导方法有效的工具书，具备理论和实操性，而且方法十分落地。比如在人际沟通的书籍中，都知道人与人之间相处需要一些技巧，不过它会强调：在赞赏时，要让对方明确感受到，并且详细解说了工作场合中可以用到的赞赏行为。\u003c/p>\u003cp>B\u003c/p>\u003cp>你是否有过真诚的赞赏对方，对方却不领情，但问题出在哪里你并不清楚？是否想创造更积极的工作环境，却无从下手？这本书里能指导你正确的人际交往方法，如果你想在职场中更好的为下属营造良好的工作氛围，都可以从这中得到一些启发和收获。\u003c/p>\u003cp>今天为大家带来的这个片段将告诉我们如何在工作场合对恰当的对同事表达赞赏，掌握和同事相处的方法，\u003c/p>","ratings_count":3,"texts":[{"id":13783,"quote":"\u003cp>\u003cstrong>R·阅读原书拆页【2分钟】\u003c/strong>\u003c/p>\u003cp>主动向同事提供帮助，是一种表达赞赏的好方式，尤其是对以服务行为为主要赞赏语的人。然而,在提供帮助的时候,我们需要注意方式方法,才能让你的帮助更有效。以下有几点建议:\u003c/p>\u003cp>帮助别人之前,先完成自己的责任。有些人太喜欢帮助别人,以至于常常“擅自离岗”—放下自己该做的事情。这种做法和小学生只顾帮助同学完成作业,自己却没完成作业一样,虽然这种行为很高尚,但这个学生自己可能毕不了业\u003c/p>\u003cp>帮助别人之前,要先征得对方同意。这一点非常重要。即便你知道对方的主要赞赏语是服务行为,也要先询问对方是否需要帮助。如果直接冲上去帮忙,而对方正好不需要,你的做法不但不是赞语,反而会让你们的关系紧张。\u003c/p>\u003cp>要主动服务。如果你希望自己的服务行为能鼓励同事,要在对方需要的时候主动伸手。等着领导指令再帮助,就不是赞赏。而是完成任务了。\u003c/p>\u003cp>审视自己的态度。有一句谚语说:以愉快的态度做事情,就如甘霖降在沙漠。这句话反过来也很有道理:以消极态度做事,就像龙卷风吹过沙漠。当你为别人提供帮助的时候,如果心不甘情不愿,就很难给别人带来鼓励。大部分人宁肯自己做,也不愿看别人的脸色。所以,要带着愉快的心情去帮助别人\u003c/p>\u003cp>如果你帮助别人,按对方的方式去做。完美型的人通常不喜欢接受别人的帮助,总觉得别人达不到自己的要求。我们提供帮助的时候,先要问清楚对方希望我们如何做。\u003c/p>\u003cp>有始有终。对那些重视服务行为的人来说,最让他们不悦的做法,就是做事情有始无终。如果你打算帮助他人,一定要把事情做完。\u003c/p>","explains":"\u003cp>\u003cstrong> I讲解【4分80秒】\u003c/strong>\u003c/p>\u003cp>工作中我们经常有和同事互相帮忙的时候。就拿我来说\u003cstrong>（反例）\u003c/strong>，上周末的时候，社群运营的一位小伙伴负责的一项任务是制作完成所有学员的入营证书。考虑到对方的工作量有点大，我就想帮助对方的承担一半的工作，想象着两个人能快速的完成工作，替她节约时间，还能使两人在分工协作中锻炼出默契。一想到帮助她这件事这么有意义立马就像对方提出了。然后开开心心的立马上手去制作证书，但是最后的结果是她以微信群昵称为准，我以打卡圈昵称为准。两个人制作的名字不一致。导致我和小伙伴重新核对了一遍我制作的证书\u003c/p>\u003cp>大多数情况下我们都会很乐意帮对方做一些事情，例如帮同事一起整理会议上需要的资料或者是帮助归理文档，但是这样做会带来什么影响呢？\u003cem>极有可能\u003c/em>等整理完后会发现和对方的要求并不相符，最后还要返工重新修改等。\u003c/p>\u003cp>比如帮同事整理文档时我们按照自己的归类方式进行了文档整理，反而不便于对方查找；准备会议资料时没有事先确认好内容，导致内容有缺少，原本的好意帮助行为反而给同事多添加了工作量或者欸没有起到帮助的效果，“好心办了坏事“。这便是没有以正确的方式帮助对方，\u003cstrong>这样造成的后果不仅是自己付出的帮助—可能是时间，金钱或者行为没有起到正向的作用，反而给对方“添乱”造成一种负担，浪费更多的时间和精力，也许还会导致对方对自身的能力或者好意产生误会。\u003c/strong>\u003c/p>\u003cp>Why\u003c/p>\u003cp>乐于助人是人的天性之一我们不会因噎废食，当然也不会因为帮助不当造成的结果而放弃帮助在乎的人。而是需要学会用正确方法帮助对方。这样就能避免用想当然的心态或者贸贸然的用自己的方式去帮助对方，使自己“帮助”的价值最大化，也更能使彼此之间因为帮助这个行为有个愉快的经历，拉近和对方的距离，建立良好的人际关系。\u003c/p>\u003cp>How\u003c/p>\u003cp>如何正确的帮助？在《赞赏的五种语言》中作者给出了方法\u003c/p>\u003cp>1.帮助别人之前,先完成自己的责任。这是帮助别人的前提。\u003c/p>\u003cp>2.帮助别人之前,要先征得对方同意。在开始之前主动询问一句我看到你很忙，需要我来分担一些么？征得对方的同意是一种礼貌的行为。\u003c/p>\u003cp>3.要主动服务。这是一个主动的行为，如果带有被动或者被强制的意味就会失去“帮助“这件事的意义。\u003c/p>\u003cp>4.审视自己的态度。主动服务的过程中，带有愉快的心情去做这件事，更能使对方感受到善意。\u003c/p>\u003cp>5.如果你帮助别人,按对方的方式去做。比如帮助对方整理文档时可以问一句，你对文档是分门别类的习惯是什么？按照对方的方式完成帮助的行为，才能使完成之后真正的帮助对方。\u003c/p>\u003cp>6.要有始有终。在帮助对方时中途停止或者走开，会导致对方有不满和抱怨的情绪，也不符合我们帮助的初衷。有始有终的帮助别人是很重要的事情。\u003c/p>\u003cp>在学了这次的拆页之后，如果再次遇到这样的事情，我会这样做（正例）\u003c/p>\u003cp>我的同事很忙碌，我想帮助一下她，\u003c/p>\u003cp>1.我会梳理自己的本职工作是否已完成，\u003c/p>\u003cp>2.然后可以询问同事是否需要帮忙，\u003c/p>\u003cp>3.我会先询问对方制作证书的格式以及注意的要点，按照对方的要求去制作。\u003c/p>\u003cp>4.并保证过程中及时沟通，让对方了解我的进度和完成状态，如果有任何的偏差，及时询问原因并修改。做到有始有终。\u003c/p>\u003cp>Where\u003c/p>\u003cp>适用于明确不属于自己的职责范围的任务。不适用于在自己职责范围内的事情。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1显像提问\u003c/strong>\u003c/p>\u003cp>接下来我们会进行分组讨论，一般为两个人一组。那就从我左手边开始，左手边三位小伙伴一组，右手边两位小伙伴一组。\u003c/p>\u003cp>请大家回想一下你有没有在工作学习生活中遇到这样的事情，自己出于好意想帮助同事分担一些工作，可能是帮对方完成一个PPT，或者是协助妈妈一起整理家务，或者帮校友整理校友资料 但是结果却好心办了坏事，反而出了差错。大家好好的想一想有没有类似的案例，打开思维，回想一下，可以和自己的小组搭档互相分享自己的案例。\u003c/p>\u003cp>【讨论时间3分钟】\u003c/p>\u003cp>讨论中。。。。\u003c/p>\u003cp>【学习者分享环节】\u003c/p>\u003cp> 刚刚看到大家很热烈的互相讨论，现在就请一位学习者来给大家分享一下自己的案例，请慢慢i小伙伴给大家分享一下。\u003c/p>\u003cp>【记录学习者分享案例】\u003c/p>\u003cp>我前段时间比较空，同事接了一个项目，做一个平台的体验设计，我就想我也是产品经理也会做，就对同事说刚好我帮你一起做吧。然后就把这件事交给我了。大概花了两天时间卡在他的截止时间做完 这件事。做完之后他看的时候对我说你这个做的太多了，我要的不是这样的，不需要这么麻烦，步骤太麻烦了。结果他又花时间做聊聊一遍，交稿的时间比他预计的时间晚了两天，也给他时间上造成了延迟。\u003c/p>\u003cp>【点评学习者案例】\u003c/p>\u003cp>非常感谢慢慢给我们分享自己在工作中遇到的案例。在这个案例中，慢慢是好心的帮助同事做一个产品体验的工作，但是因为没有提前沟通，导致同事不得不将工作返工，不但没有帮到忙，还浪费了双方的时间。相信这并不是我们想要达到的结果，对么？\u003c/p>\u003cp>\u003cstrong>A1反思加工【4分钟】\u003c/strong>\u003c/p>\u003cp>相信学习完这个拆页之后，大家都已经掌握了如何正确帮助别人的技能。那么接下来就请大家回想一下 自己刚刚在组内分享的案例，假如你回到了当时事情发生之时，你会如何运用这个拆页知识，使自己的主动帮助行为真正的帮助到了你的同事。大家可以在自己的小组内互相讨论分享一下。\u003c/p>\u003cp>【讨论时间2分钟】\u003c/p>\u003cp>讨论中.。。。。。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>我们请慢慢分享一下，假如回到了你分享的案例发生的事情中。你会如何应用拆页技能做呢？\u003c/p>\u003cp>【学习者分享的反思案例】\u003c/p>\u003cp>我会先确定自己的工作是否已经完成\u003c/p>\u003cp>做之前先跟他沟通他是否需要我做这件事请，\u003c/p>\u003cp>做之前提前和他沟通清楚他到底想要一个什么样的界面，按照对方想要的一个界面去设计。这个时候带着一个很开心的态度去做。\u003c/p>\u003cp>时刻和他保持沟通，跟进的后面的进度。做到有始有终。\u003c/p>\u003cp>【点评学习者案例】\u003c/p>\u003cp>谢谢慢慢小伙伴给我们分享自己的反思环节，通过刚刚的分享能发现小伙伴们对拆页的知识点掌握的都比较熟悉 。\u003c/p>\u003cp>【总结】\u003c/p>\u003cp>最后来总结一下今天的拆书\u003c/p>\u003cp>主题是如何正确帮助别人，\u003c/p>\u003cp>目的是帮助学习者掌握和同事/好友/家人之间的相处时互相帮助的方法，而不再是好心办坏事。\u003c/p>\u003cp>那么我的拆书分享就到这里，谢谢大家\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1592146882000,"updated_at":1595164392000,"ria":true},{"id":9838,"topic":"表扬成就","learn_goal":"","remark":"这是一本是由《爱的5种语言》的作者盖瑞·查普曼和工作人际关系学家保罗·怀特共同编著的职场人士必读书目。 本书主要讲述的是在工作场合如何巧妙的运用赞赏，迅速改善工作气氛，打造积极高效的工作团队的方法。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"李霞Sally","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"\u003cp> 哈喽，大家好，我是李霞Sally，我今天的分享选自《赞赏的5种语言》这本书中的‘肯定的言辞’。我的分享将从自我介绍、介绍拆书和拆书帮和今天的拆页‘表扬成就’三个方面进行。\u003c/p>\u003cp>首先我用三张标签来做\u003cstrong>自我介绍\u003c/strong>。 第1张标签，大健康行业的质量人。我的职业生涯一直和两个比较敏感的词相连接着，就是‘保健食品’和‘直销’。我是一家保健食品直销公司产品供应链的质量管理人员。 第2张标签是精时力的践行者。我是从2019年的3月开始，每天早上听拆书帮上海喜乐分舵的三级拆书家，崔律的精时力早课，也从这个时候开始了每天的早起生活。 第3张标签是我是一个有证的潜水爱好者。我是一名有3年潜龄，但还不足50罐气的、有证的初级潜水爱好者 好了，这就是我，一个将保健食品、直销、早起、潜水链接在了一起的Sally李霞。\u003c/p>\u003cp>【拆书帮介绍】\u003c/p>\u003cp>第1次接触\u003cstrong>拆书\u003c/strong>这个词的时候，我会以为拆书就是把书拆开，把它分成一页一页的看，但实际上拆书是一种学习方法，适用于成人的学习方法。它是以提升能力、解决问题为目标的成人学习法。我们之前上学的时候，是以学习知识为中心，而拆书法强调是以学习者为中心，要用知识关联学习者的经验规划具体的运用场景。\u003c/p>\u003cp>\u003cstrong>拆书法\u003c/strong>分为两种，一种是供个人学习的拆书法，一种供组织学习的拆书法。供个人学习的拆书法，主要是运用便签学习法，让我们自己读一本致用类图书的时候能够达到和参加同类主题培训一样的效果。而供组织学习的拆书法是由一位拆书家将一本书加工成一场现场的培训，引导和促进一群人把知识拆为己用。所以如果以学习者的学习效果来衡量的话，一位拆书家所创造的价值不亚于一位培训讲师。\u003c/p>\u003cp>\u003cstrong>拆书帮\u003c/strong>是基于拆书法的学习爱好者的一个社群，是一个非营利性的青年自组织。它的使命，是以释放学习者的能量，让更多的学习爱好者成长为拆书家。有一种通俗的方法说，拆书帮就好比医学院，医学院培养的是医生，而拆书帮培养的就是拆书家。在医学院毕业的医生就可以在医院里治病救人；而拆书帮培养的拆书家毕业后，同样可以在拆书学院帮助更多的人解决在个人成长过程中实际遇到的问题。 \u003c/p>","ratings_count":2,"texts":[{"id":13679,"quote":"\u003cp>\u003cstrong>表扬成就\u003c/strong>\u003c/p>\u003cp> “肯定的言辞”的表达方式之一，就是通过语言来表扬一个人，而表扬的焦点集中在他取得的成绩或成就上。当工作团队中有的人工作完成得非常好，达到其至超过了我们的期望时，我们就会用到这种方式。这是吉姆最喜欢的方式，表扬会让他工作起来更有劲头。\u003c/p>\u003cp> 在工作场合，这是很常见的赞赏方式。企业或团队存在的目的，就是为了完成某项使命。当团队的一员对这项使命做出卓越贡献时，得到表扬是很应该的。\u003c/p>\u003cp> 这种方式的表扬通常集中在具体的事情上。“罗伯特，你今天上午的报告真是太棒了。我喜欢你引入国际化因素。我们需要在这方面多下工夫，谢谢你提醒了我。”\u003c/p>\u003cp> \u003cstrong>表扬越具体，效果越明显。\u003c/strong>当你看到某位志愿者或员工按照你喜欢的方式工作时，立刻给予表扬，他下一次会更有可能重复同样的行为。人类行为方式的研究印证了这种理论。“我喜欢你接电话时开心的语调，以及你主动为客户提供帮助。”你这样说，接待员下次还会这样做。说“谢谢你这么早就来做准备，让我们能够准时出发”， 远比说“谢谢，你今天做得不错”要有意义得多。\u003c/p>\u003cp> 事实证明，那种泛泛而谈的表扬，如“做得不错！”“你是个好学生！”基本上起不到鼓励的作用，也不能增加积极的行为，甚至会让人泄气。常有员工说：“我最讨厌老板说：‘大家做得不错！路还长呐！加油啊！’这哪是鼓励，简直是诅咒。”再强调一遍：要让表扬有效，就必须具体。\u003c/p>","explains":"\u003cp>今天的主题，肯定的言辞之表扬成就。先给大家介绍一下，今天的这个拆页选自《赞赏的5种语言》这本书。这本书的英文书名是the five languages of appreciation in the work place。从英文的书名中，我们可以读出3个信息，首先这本书主题就是赞赏，第二它主要讲的是5种赞赏的语言，也就是5种赞赏的方式，第3这本书主要讲的是在工作的场合如何来应用这5种赞赏的语言来表达我们的赞赏。这本书是非常热销的《爱的5种语言》的姐妹篇。这本书的作者是美籍的盖瑞·查普曼，他就是《爱的5种语言》的作者。另外一名作者是保罗·怀特，他是一名资深的心理学家，工作人际关系专家。这本书主要介绍的5种赞赏的语言，分别是：肯定的言辞，精心时刻、服务的行为、称心的礼物和身体接触。今天跟大家拆解的片段，就来自于5种赞赏的语言的第一种，肯定的言辞。\u003c/p>\u003cp>在正式拆解前我想问一下大家，在日常的生活工作当中，你会经常的赞赏别人吗？你是怎么称赞别人的呢？下面哪种是你经常使用的称赞别人的话呢？我举了5个例子请大家拿出笔和纸记录一下你在日常工作当中经常说的语言。第1个，哇哦，你今天的表现简直太棒了！第2个，大家今天做的都不错！继续加油啊！第3个，谢谢你这么早来做准备，让我们可以准时出发。第4个，你今天上午的报告简直太棒了！我特别喜欢你引入国际化的这个内容，让我耳目一新，以后我们要多往这方面下功夫。第5个，你补充的这个点太赞了，从检查者的角度发现了一个我们之前忽略的点，我们把这个点补充后就更有信心通过这次审核了。以上5个使用赞赏语言的例子，你平时工作中或者是生活工作中最经常使用的是哪一类呢？请把它的编号记录下来。\u003cbr>\u003c/p>\u003cp>这个片段是来源于《赞赏的5种语言》中 ‘肯定的言辞’中的一种‘表扬的成就’。\u003c/p>\u003cp>【WHAT】\u003c/p>\u003cp>\u003cstrong>什么是表扬成就？\u003c/strong>表扬成就，就是当别人取得了成绩和成就的时候，我们用正面的语言来表扬、赞赏他的成绩和成就，这是我们在日常工作当中最常用的一种赞赏别人的方式。在使用的过程当中有一点是值得注意的，就是我们表扬的时候要\u003cstrong>表扬他的具体的行为\u003c/strong>，越具体越能够凸显出我们对他的\u003cstrong>表扬和赞赏不是泛泛而谈，而是发自内心的\u003c/strong>。\u003c/p>\u003cp>【WHY】\u003c/p>\u003cp>\u003cstrong>为什么这样说呢？\u003c/strong>我们可以举个例子来说。比如我们说，“你今天上午的报告真是太棒了。”如果我是做报告的人，我在接收到这个表扬的时候，我的第一反映一定是非常开心，因为对方在表扬我呀。\u003cstrong>那么，问题来了，然后呢？\u003c/strong>在开心之后呢？我还接收到什么样的信息呢？没有了，对吗？\u003c/p>\u003cp>但是，如果我们在这句话后面再加一句对报告里具体的内容的一个描述，那它所呈现出来的结果就会完全不一样，比如我们说，“你今天上午的报告简直太棒了，尤其是加入国际化因素这个点，让我耳目一新、非常受用，以后我们要在这方面多下功夫，谢谢你的提醒。”发现没，在泛泛的赞赏语之后，加上具体表扬的行为，作为受到赞赏的我来说，除了高兴之外，我\u003cstrong>发现他对我的赞赏是发自内心\u003c/strong>，因为他表明了他对我赏识的具体的点是报告引入国际化的分析。另外在这个时候，我还接收到了一个重要信息，他喜欢我在报告中引入国际化分析。\u003c/p>\u003cp>\u003cstrong>那么，问题又来了，然后呢？\u003c/strong>在你知道报告之所以好的点在引入国际化这个点之后呢？如果再有类似的报告，你可能还会怎么做吗？当我们表扬的是某人的具体的一个行为的时候，作为表扬者来说，这个行为肯定是我非常欣赏和赞赏的点；作为被表扬者来说，当他再遇到类似的情况时，因为他知道了这么做很好，他会有很大的可能还会这么做。所以，我们可以再拓展一点：在我们赞赏某个人的时候，我们在表扬他的具体行为时，这也是\u003cstrong>一个引导性的语言，引导他未来行为的方向\u003c/strong>。所以赞赏的语言，除了可以激励工作时的伙伴or员工外，还能起到强化行为的目的，也就是在未来让他重复这样行为的作用。\u003c/p>\u003cp>另外一个要注意的点：\u003cstrong>‘及时’反馈\u003c/strong>。发现对方的亮点，在第一时间反馈，效果是最好的。因为这个时候，我们的感受是最强烈的，所以表达出来的赞赏的情感是最强烈的，而对方接受到的赞赏也是最强烈的，随着时间的推移，这份‘强烈’会逐渐减弱。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>那我们应该具体怎么做呢？\u003c/strong>首先要发现值得表扬的具体的行为。怎么发现呢？通过‘比较’的方法发现，我们可以通过比较‘他的过去’和‘他的现在’，发现他的进步的具体行为；比如文中的栗子：你的报告太棒了！那这个棒的点是哪里呢？加入了国际化的因素分析，这就是他的现在和过去比较之后进步的具体行为。当然我们还可以通过他和别人的比较，他和我的预期的比较等等，来发现他值得表扬的具体行为。当我们发现的时候，我们就可以进行第2步了，立刻、大声的说出，给予对方表扬。\u003c/p>\u003cp>表扬成就，是我们在工作中最常用的一种赞赏的方式，但其实它在我们\u003cstrong>日常的生活中也可以经常应用\u003c/strong>，比如说在朋友间、在家人间同样可以使用。我记得在儿子刚上的小学的时候，每天我回家都会问他，“作业写完了吗？”只要他在我回来前完成了当天的作业，我就会立刻表扬他，“这么快呀，在妈妈回来前自己就把作业写完了，真厉害。”直到现在，他在完成作业的速度上，从来不用我操心。\u003c/p>\u003cp>好了，让我们再回过头来看一下，在拆页之前我们看到的这5句话，它们之间有什么不一样的地方呢？发现了吗？第1句和第2句只是有肯定的言辞，没有具体的内容，所以我们不知道我们具体哪里做的很好。而第3句、第4句、第5句，除了有赞赏语以外，我们还接收到了信号“欧，我们之所以被赞赏，是因为我们这些地方做的好。”这时我们在潜意识里也会自然的知道，这些地方是我们未来可以继续做的更好的地方。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>在读了这本书之后，在4月下旬的一天下午，我就在一次和部门的小伙伴们一起讨论‘迎接外部检查’事情的时候，在整理完，整个需要准备的内容之后，我又问了一句：‘大家看看还有什么遗漏的，需要再补充的吗？’这个时候就有一个小伙伴W说：‘我们对外的所有反馈单据都是齐全的，但是还缺一份关于这次市场反馈的内部纠偏的单据。’我当时心想，‘她想到了一个我们大家都忽略掉的点，在这个点上她超越了我们所有人。’于是，我立刻就说：‘哦，对了！你真是太棒了！还好你想到了！是的，我们还要补充一份这次市场反馈的内部纠偏的报告，要不然的话我们就会出现重大的一个漏洞，谢谢你的提醒。’当时，从小伙伴的眼神当中，我是看到了一丝光亮，我知道：嗯，这句话对她来说应该是很受用的。如果在没读这本书之前，我想只会说到‘你真是太棒了！’不会往后再说。通过《赞赏的5种语言》，让我在表达赞赏的同时增加了具体的内容的描述，也会让她更明确的接收到自己被赞赏的地方。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>我的A2是：部门的月报是每个小组轮流进行汇总总结的，这个月轮到了工艺组的同事J。我发现第1次做月报汇总的他，有一个非常大的优点，就是：之前的同事，只是对当月数据进行汇总，而同事J在4月月报的基础上，增加了和3月数据的对比，使得数据更丰满，说服力更强。\u003c/p>\u003cp>我计划在5月6日上班后和工艺组的小伙伴J反馈一下，我打算这样说：4月份的月报我看完了，第一次做部门月报就做成这样，非常的棒！我看到你在月报中增加3月数据，并且进行了对比说明，使得整体数据显得更丰满、更有说服力。相信领导看完之后也会更加详细的了解到我们部门工作这一个月所取得的成绩。\u003cbr>\u003c/p>\u003cp>好了，简单的一句赞赏语，再加上一点对具体行为的描述，会让对方感受到我们的赞赏是发自内心的，同时会拉近我们和小伙伴之间的认知距离，也会让我们工作氛围更愉快，工作进度更顺畅。所以，赶快用起来吧！\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1590322186000,"updated_at":1591774163000,"ria":true},{"id":9818,"topic":"处理好人际关系最关键的一点","learn_goal":"","remark":"今天我带来的拆页选自《赞赏的5种语言》这本书，这本书的两位作者，盖瑞查普曼博士所著的畅销书全球热销六百多万册，是享誉全球的辅导专家，保罗怀特博士则是一名资深心理学家，工作人际关系专家，作家和讲师。他持续深入的研究如何建立和改善健康的人际关系。这本书可以帮助你在不同场景下如何来改善人际关系。","level":"TF1-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"牛牛不想乖","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"\u003cp>大家好，我是牛牛不想乖，先向大家用三个标签自我介绍一下。\u003c/p>\u003cp>第一个标签我的本职工作是一名电商行业从业者，\u003c/p>\u003cp>第二个标签我是一名正在跟着我师父裘叔锻炼拆书技能的小白拆书家，\u003c/p>\u003cp>第三个标签是精时力的践行者\u003c/p>\u003cp>今天我带来的拆页选自《赞赏的5种语言》这本书，这本书的两位作者，盖瑞查普曼博士所著的畅销书全球热销六百多万册，是享誉全球的辅导专家，保罗怀特博士则是一名资深心理学家，工作人际关系专家，作家和讲师。他持续深入的研究如何建立和改善健康的人际关系。而这本书可以帮助人们在不同场景下运用具体的方法来改善人际关系。 \u003c/p>\u003cp>我分享的拆页主题是---《处理人际关系最关键的一点》 \u003c/p>\u003cp>下面我将通过共享屏幕的方式分享原文片段，请大家阅读原文，阅读完成后，可以在聊天界面框回复1，提示我已阅读完毕。\u003c/p>","ratings_count":7,"texts":[{"id":13660,"quote":"\u003cp>有些管理者在倾听方面受过的训练很少,他们也许可以在众人面前侃侃而谈、发号施令,但是一到倾听就力不从心。学习倾听也许跟学一门外语一样难;但是,如果想让人们感觉被赏识,我们就必须要学。这对那些主要赞赏语是精心时刻的员工尤为重要。幸运的是,市面上有很多关于倾听的书籍和文章,我们在此就不再赘述,只是简单列几个有用的小技巧:\u003c/p>\u003cp>1.保持眼神交流。控制自己,不要看天花板、地面,不要望着窗外或盯着电脑屏幕。你若看着对方,就不容易走神,同时也是在告诉对方:你在专心听他讲话。\u003c/p>\u003cp>2.倾听的时候,不要做其他事情。有些人总以自己能一心多用为荣。这虽然让人羡慕,但若在倾听的时候这样做,会让对方觉得你对他的话不感兴趣。\u003c/p>\u003cp>3.聆听想法,体会感受。听的时候,你要想:“他此时此刻是什么感受呢?”你可以通过提问来确认。你可以这样问:“这次没有升职,让你觉得很失望、很受伤,对吗?”通过提问,对方可以进一步澄清自己的感受。这样做也是在告诉对方,你在专心听他讲话\u003c/p>\u003cp>4.即使观点不同,也要肯定对方的感受。我们都是感情动物,忽视了情感,等于忽视人性中重要的部分。如果一位经理先对下属说“我理解你的感受,如果我是你,肯定也会这样想的”,然后再说“让我解释一下公司为什么会做这样的决定”。由于先肯定了他们的感受,你就是他们的朋友了,他们就更愿意听你的解释。\u003c/p>\u003cp>5.留心对方的肢体语言。紧握的双拳、颤抖的双手、闪烁的泪光、紧蹙的眉头、漂移不定的眼神……这些都会说明,这个人的情绪如何。有时,人们嘴里说的话,和身体语言所表达的真实想法不完全一样。因此,我们在倾听的过程中,要和对方核实,确保自己能理解对方真实想法和感受\u003c/p>\u003cp>6.不要插话。研究表明,一般人能够安静聆听的时间只有17秒,然后就想插话、给建议。全神贯注倾听,意味着在听的时候,克制自己,不辩护、不反驳,不固执已见坚持自己的立场:我的目标是明白你的想法和感受，不是为自己辩护，改变你，我想理解你。相互理解能建造积极关系，而辩解会创造敌人。\u003c/p>","explains":"\u003cp>【what】你有没有过这种经历，有一天工作上遇到了令自己心塞的事情，回到家就想向闺蜜或者老公吐槽倾诉。结果对方时不时的打断你的话表达自己的看法甚至还会批评你，要么就是一边刷小视频一边抬头偶尔的附和几声。倾诉不仅没有得到安慰，反而和对方因事就事产生分歧令两个人都不愉快，你有过这样的经历么，你想过改变这样的问题么？其实这样的例子在我们的生活中并不陌生，就拿我最近的一件事请来说，我最好的闺蜜最近一直都在纠结是否跳槽，视频时她在跟我说话时我并正在一边做手头上的家务一边聊天，没有认真的看对方也没有认真的听对方说自己最近的苦恼，中间我还有打断对方的话表达自己的看法。在这件事上我就没有认真的倾听对方的话。\u003c/p>\u003cp>【why】要解决上面类似的问题，就需要学会一个方法--正确的倾听。正确的倾听好处是它可以使我们在工作中帮助信息被有效传递，建立良好和谐的工作关系。和家人沟通时，善用倾听的姿态可以更佳的传递情感与情绪，增进家人之间的亲密关系， 避免因意见分歧产生隔阂。\u003c/p>\u003cp>【how】那要如何学会在沟通中正确倾听呢？在《赞赏的五种语言》中，作者列出了简单有用的几个方法：\u003c/p>\u003cp>1.认真的看着对方的眼神，有眼神的交流。\u003c/p>\u003cp>2.在倾听中，保持专注，向对方传达出你在认真听的态度。\u003c/p>\u003cp>3.体会对方内心真实想法和感受，并进行确认。\u003c/p>\u003cp>4.将对方的感受放在第一位，先进行肯定。\u003c/p>\u003cp>5.留意对方肢体语言，寻找背后的潜台词\u003c/p>\u003cp>6.在倾听的过程中，要克制自己，不要插话。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>倾听的方式并不是适用于所有场合的，一般来说在较为正式场合的交流沟通使用会更好，并且不适用于一般的闲聊。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1：激活经验】\u003c/strong>\u003c/p>\u003cp>倾听的六个步骤，相信大家已经基本了解了。和大家分享两个场景，可以回想一下是不是很熟悉。\u003c/p>\u003cp>闺蜜向你吐槽一件令人不愉快的事情，但是你边听对方说话却急于表达自己的评论或者事情而忽略了她的感受；或者你正在和男朋友讨论一件事 可是你一直站在自己的角度表达感受 忽略了对方的情绪和想法，原本愉快的气氛变的糟糕，两个人都闷闷不乐甚至当天的约会也会不欢而散，影响双方的关系。类似的场景你有经历过么？那么请大家回想一下，我们有没有由于倾听不当而造成这样不好的事情呢？下面我会进行分组，两两一组，时间为5分钟，大家点击分组进行分会场可以和组内的小伙伴分享自己的例子。\u003c/p>\u003cp>好，看到大家在自己组内分享的都很热烈，下面我将请一名小伙伴分享一下他的案例，请黎影小伙伴来分享一下吧。\u003c/p>\u003cp>\u003cstrong>【学员案例分享】\u003c/strong>\u003c/p>\u003cp>上周在工作时，和对接部门的同事沟通一项任务的分配。在沟通前我就抱着在我的立场上我的做法是对的的想法，对对方的话没有拿出耐心先倾听下去。在对方表达时，我的内心是你的情况是你的事情，我的工作又不负责这些。这种心理可以想见对方肯定也感受到了我不是很友好的态度，他的想法我不仅没有好好倾听中途还好几次都打断对方的话。我们都各自站在自己的立场上坚持自己的看法。 虽然最终的结果是按照我的预期处理好了。但是沟通的过程，我们还是有一点不愉快的，也对我俩之间的关系有一些影响。这样的处理方式也不是最佳的可取的方法。\u003c/p>\u003cp>感谢黎影小伙伴的分享，\u003c/p>\u003cp>\u003cstrong>【A2：催化应用】\u003c/strong>\u003c/p>\u003cp>在A1环节大家都互相分享了自己的过去的案例，相信大家对今天的拆页知识如何正确倾听的技能掌握的很好了，那请大家运用我们今天的知识点，接下来的一周内，你会如何使用倾听六个技巧与同事/家人/朋友等等你身边的人沟通时呢？限时2分钟，请大家写下来，记住我们的A2不能仅仅是表决心，比如我要早起学习就是表决心，例如我周一开始要五点半起床，阅读20页的书籍，就是具体的做法，明确的时限，要有可衡量或可观测的预期结果，\u003c/p>\u003cp>【学员案例分享】\u003c/p>\u003cp>背景介绍：闺蜜最近一直在纠结是否跳槽，想和我聊聊这件事。但因为最近太忙而忽略了她，一直没来的及听她倾诉。\u003c/p>\u003cp>目标：本周末运用倾听的方法倾听她最近跳槽的困惑，纾解她烦闷的心情，也弥补最近对她的忽略。\u003c/p>\u003cp>1.主动和闺蜜视频聊天\u003c/p>\u003cp>2.先倾听听对方想要跳槽的原因。\u003c/p>\u003cp>例如在倾听过程中认真看着她，听她说话，专注沟通不做其他分散注意力的事情。\u003c/p>\u003cp>3.在倾听过程中，判断对方的感受。\u003c/p>\u003cp>比如在对方说完后最近在公司遇到的一件事，表达肯定对方感受的话语。\u003c/p>\u003cp>4观察对方的表情和神态。\u003c/p>\u003cp>5.在对方表达中不插话，等对方说完后再表述。\u003c/p>\u003cp>6.安慰她。比如告诉她想要做出改变，肯定也会面临未知的担忧。不要过分担心，要相信自己的判断等。\u003c/p>\u003cp>好的，小伙伴们都写完么，那我们今天来总结一下分享的拆页，主题是处理人际关系最关键的一点，可以通过六个步骤来指导人们在沟通中的应该主要的要点。\u003c/p>\u003cp>希望今天的拆页能帮助到大家，祝大家的人际关系越来越融洽。我的拆书分享就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1589724215000,"updated_at":1594196818000,"ria":true},{"id":7226,"topic":"站在对方角度认真倾听，理解对方感受","learn_goal":"倾听时学会角色互换，认真感受对方情绪及感受","remark":"","level":"TF1-1","duration":11,"status":30,"type":0,"chaishujia":{"username":"马宁","city":"银川"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>【自我介绍】&nbsp;\u003c/p>\u003cp>妮妮，国企普通职员，拆书家晋级路上的菜鸟一枚，关注育儿及自我成长，希望通过拆书解锁新技能，真正做到拆为己用，在2019年剽悍成长，不断精进。&nbsp;\u003c/p>\u003cp>【拆书帮介绍】 &nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>、什么是拆书？拆书\u003c/strong>是一种学习方法，适用于想通过拆书来提升能力，解决问题的人来学习的，拆书的目的是让知识为我所用，即使一本书没有读完，也可以用拆书法来做到拆为己用。\u003c/p>\u003cp>当你学会这种能力的核心后，你看到的就不仅仅是知识本身，还会联想到现实中的实际情况、实际问题、如何应用等等，通过读一本书引发思考来改变自己的行为。\u003c/p>\u003cp>2、\u003cstrong>什么是拆书帮？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书帮\u003c/strong>是以把更多的学习爱好者培养为拆书家为使命，以热爱拆书学习法的青年组织在一起的一个公益性组织。他们热情满满，无偿的帮助大家在拆书路上不断的升级打怪，让每个人都能拆为己用，做到理论与实际相结合。现全国共有47个正式分舵，还有若干个分舵正在筹备中。目前银川的分舵正在筹备中，分舵就是你想要学习RIA便签拆书法的组织，快来加入吧。\u003c/p>\u003cp>了解了拆书及拆书帮后，我们开始今天的拆书环节，今天我带来的拆页，选自《赞赏的五种语言》。这本书由美国《纽约时报》百万畅销书作家查普曼博士与资深心理学家，工作人际关系专家，作家、讲师怀特博士共同编写。我从中节选了一个片段进行拆解，我们一起来看一看这则片段，阅读时间大约为1.5分钟，如果大家看完了，请举手示意我。\u003c/p>","ratings_count":2,"texts":[{"id":10636,"quote":"\u003cp>【原文】幸运的是，市面上有很多关于倾听的书籍和文章，我们在此就不再赘述，只是简单列几个有用的小技巧:\u003c/p>\u003cp>1、保持眼神交流。控制自己，不要看天花板、地面，不要望着窗外或盯着电脑屏幕。你若看着对方，就不容易走神，同时也是在告诉对方:你在专心听他讲话。\u003c/p>\u003cp>2、倾听的时候，不要做其他事情。有些人总以自己能一心多用为荣。这虽然让人羡慕，但若在倾听的时候这样做，会让对方觉得你对他的话不感兴趣。别忘了，精心时刻的关键是给予对方你的全部注意力。如果你当时正忙，分身无术，你可以坦白说明:“我知道你现在想和我聊聊，我也很有兴趣。但是我现在有点急事，你能不能等10分钟，我把手上的事情处理完，再好好聊?”大多数人都会尊重这个请求。\u003c/p>\u003cp>3、聆听想法，体会感受。听的时候，你要想:“他此时此刻是什么感受呢?”你可以通过提问来确认。你可以这样问:“这次没有升职，让你觉得很失望、很受伤，对吗?”通过提问，对方可以进一步澄清自己的感受。这样做也是在告诉对方，你在专心听他讲话。\u003c/p>\u003cp>4、即使观点不同，也要肯定对方的感受。我们都是感情动物，忽视了情感，等于忽视人性中重要的部分。如果一-位经理先对下属说“我理解你的感受，如果我是你，肯定也会这样想的”，然后再说“让我解释一下公司为什么会做这样的决定”。由于先肯定了他们的感受，你就是他们的朋友了，他们就更愿意听你的解释。\u003c/p>\u003cp>5、留心对方的肢体语言。紧握的双拳、颤抖的双手、闪烁的泪光、紧蹙的眉头、漂移不定的眼神....这些都会说明，这个人的情绪如何。有时，人们嘴里说的话，和身体语言所表达的真实想法不完全一样。因此，我们在倾听的过程中，要和对方核实，确保自己能理解对方真实想法和感受。\u003c/p>\u003cp>6.不要插话。研究表明，一般人能够安静聆听的时间只有17秒，然后就想插话、给建议。全神贯注倾听，意味着在听的时候，克制自己，不辩护、不反驳，不固执己见坚持自己的立场:我的目标是明白你的想法和感受，不是为自己辩护、改变你，我想理解你。相互理解能建造积极关系，而辩解会创造敌人。\u003c/p>\u003cp>我们的意思并不让你闭口不提自己的观点和感受。但如果你谈话的目的是想要通过精心时刻对员工表达赞赏，第一优先是理解他们的想法和感受。当你正确聆听了，就可以分享自己的观点。希望在你好好聆听的示范作用下，他们也能好好聆听。当双方都能设身处地聆听对方时，以精心时刻为主要赞赏语的员工，就会感受到被鼓励和赏识。\u003c/p>","explains":"\u003cp>\u003cstrong>主题：\u003c/strong>站在对方角度认真倾听，理解对方真实感受\u003c/p>\u003cp>好的，我看见大部分小伙伴已经看完了，那我们来看一下，原文用6步法告诉我们如何进行倾听，我想大部分人可能记住的也只是其中的几点而已，那今天我总结概括了四点，让你轻松掌握倾听技巧。\u003c/p>\u003cp>\u003cstrong>（what）首先，什么是\u003c/strong>\u003cstrong>倾听？大家有没有想过这个问题呢，百度文库的解释是这样的，倾听\u003c/strong>属于有效沟通的必要部分，以求思想达成一致和感情的通畅。狭义的倾听是指凭借听觉器官接受言语信息，进而通过思维活动达到认知、理解的全过程;广义的倾听包括文字交流等方式。其主体者是听者，而倾诉的主体者是诉说者。两者一唱一和有排解矛盾或者宣泄感情等优点。\u003c/p>\u003cp>倾听者作为真挚的朋友或者辅导者，要虚心、耐心、诚心和善意为诉说者排忧解难。而今天我们所说的倾听，属于广义性质的倾听，更注重于倾诉者的感受。\u003c/p>\u003cp>\u003cstrong>(Why):\u003c/strong>了解了什么是倾听，我们再看看为什么要认真倾听？一方面认真倾听有助于彼此间亲密关系的建立和延续，建立较好的人际关系和个人品行，另一方面会让对方感觉的他对你而言很重要，增强彼此间的信任感。\u003c/p>\u003cp>\u003cstrong>（how）\u003c/strong>了解了什么是倾听，为什么要认真倾听，我们再看看如何倾听？说到这，我想很多人都会认为，不就是听人说话吗，有什么难的，你可以问问自己，上次和朋友一起时，你真的认真听了吗，你能感受到她肢体语言和情绪的细微变化吗？如果没有，也许看了这四步，你也许就知道怎样倾听最有效。\u003c/p>\u003cp>\u003cstrong>第一步：放下手中的一切，保持专注。\u003c/strong>放下手中正在做的事情，保持专注和适当的眼神交流会让对方感受到你的真诚用心，当你对对方报以全部的注意力时，对方能用心感受到他在你心中的重要性。\u003c/p>\u003cp>\u003cstrong>第二步：留心对方的肢体语言。\u003c/strong>关注对方的肢体语言有助于我们增强对对方的理解和情绪判断，关注他的微表情、微动作判断他当时的真实感受。在表述过程中，可能对方紧握的双手，或是不安的眼神都是对方真实情绪的表达，这时我们可以通过对方说的话和身体语言，来判断对方的倾诉是不是自己内心真实的感受，确保自己所领会的就是对方所表述的。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步：理解对方。\u003c/strong>\u003c/p>\u003cp>1、站在对方角度理解对方感受，既使观点不同，也要先认同对方当时的感受，接纳她的情绪。\u003c/p>\u003cp>2、尊重。不打断对方来表达自己的观点。明确自己倾听的目的是理解对方的感受，而不是表达自己的观点，感同身受而不是改变对方。\u003c/p>\u003cp>\u003cstrong>第四步： 回应与引导。\u003c/strong>\u003c/p>\u003cp>1、当对方还没表述完或情绪状况较差时，可以有适当的身体接触，比如握住对方的手，或是拍拍后背，用微小的互动，表达你对他安慰。\u003c/p>\u003cp>2、当对方表述结束后，先予以理解，进而适时给予安慰，不轻易替对方做评判。可以帮助对方做回顾，用提问的方式进行引导，让对方发现和反思问题所在，更好的解决对方的困惑。\u003c/p>\u003cp>&nbsp;\u003cstrong>(WHERE):\u003c/strong>问题来了，那有了一系列的步骤后，这个方法适合用在哪里呢？我个人认为适用于朋友间的倾诉聊天时刻，与较为亲近的人沟通时刻，这都适用的。\u003c/p>","interaction":"\u003cp>【A1】描述自己的相关经历\u003c/p>\u003cp>下面我要给大家讲个我的小故事了：\u003c/p>\u003cp>女朋友P是我的大学同学，每次我们见面聊天时，她都在给我倾诉创业艰难，心很累。18年11月15日，我们又见面聊天，她又向我倾诉生活中的不易，因为听了太多次，也没什么耐心，所以就边玩手机，边听她讲，时不时的嗯一声。没过一会儿，她看我似乎没什么兴趣，也就不在说话，见面很快结束。随即在之后的一个多月的时间里，都没有再联系。\u003c/p>\u003cp>反思自己上次与朋友P的会面，一方面是自己听的太多没有耐心了，另一方面是觉得不知怎么去听她说才能做到感同身受。\u003c/p>\u003cp>如果再来一次，我一定放下手中真在做的事，直视对方，认真听她倾诉.\u003cstrong>(\u003c/strong>\u003cstrong>专注\u003c/strong>\u003cstrong>)\u003c/strong>\u003c/p>\u003cp>站在她的角度来理解一个女性创业者的艰辛。通过她的肢体语言和微小变化来感受她当时的心情如何，她的真实感受是怎样的，确保自己领会的和她所表达的内容一致，而不是拿起手机去刷朋友圈，安静的听完全部。\u003cstrong>（关注肢体语言，理解她）\u003c/strong>\u003c/p>\u003cp>在听的过程中，我会在她讲到激动之处，拍拍她的后背或是抓住她的手，进行安慰，在结束倾诉时，会拥抱她或是轻拍她的后背，用语言和行动表示我的理解。帮她回顾一下讲的过程有哪些地方可以做的更好，遇到困难是什么原因，有什么解决的办法等等，引导她一步步完成反思。最后我要鼓励她，希望她可以再接再厉去迎接挑战，一定会有自己的一片天空。\u003cstrong>（回应与引导）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2】应用\u003c/strong>\u003c/p>\u003cp>【场景】我打算在19年春节后的周末约这位P同学出来聚会。\u003c/p>\u003cp>【明确的目标】聚会时会问她最近怎么样，聊天中请她说说自己创业的相关事情。\u003c/p>\u003cp>【具体的行动】在聊天或她倾诉时，我会放下手中正在忙的事情，保持专注和适当的眼神交流，让她感知到我在认真的听她说话。\u003cstrong>(\u003c/strong>\u003cstrong>专注\u003c/strong>\u003cstrong>)\u003c/strong>\u003c/p>\u003cp>而后，在说的过程中，站在一个女性创业者的角度来理解她面临的种种问题，通过她的肢体语言和微表情、微动作来判断她的真实感受，理解她的不易，让她痛快的\u003c/p>\u003cp>说完自己的困惑与不易，而不是打断她，尝试帮她分析问题，在倾诉期间，我会在她较为难过或是激动时，握住她的手，或是轻轻拍拍她的后背，用我的行动告诉她，我是理解她，心疼她的。\u003cstrong>（关注肢体语言，理解对方感受）\u003c/strong>\u003c/p>\u003cp>在结束倾诉时，我会握住她的手，对她说：我理解你，亲爱的，一个女性出来创业本来就会面临很多问题，你可以回想一下，在你做这件事的时候，有哪些地方没有做好，或者是可以做到更好的地方，那些地方可以不去做………..亲爱的，其实你已经做得很好了，你是我的榜样，要对自己有信心，你今后会更好的，加油。然后起身抱抱她。\u003c/p>\u003cp>\u003cstrong>（引导与回应）\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1550538428000,"updated_at":1550538958000,"ria":true},{"id":4031,"topic":"如何让表扬更有效","learn_goal":"学会有效的表扬方式，让对方感受到真诚的肯定","remark":"","level":"TF1-1","duration":10,"status":0,"type":0,"chaishujia":{"username":"王倩倩","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"【自我介绍】大家好，我是王倩倩，今天我要拆的是TF1-1，很开心站在这里开始我的升级打怪之旅。我的三个标签是，第一个标签，我是一名高校教师，第二个标签，我是一名家庭阅读指导师和家庭教育指导师，第三个标签，我是一名未来拆书家。生命不息，成长不止，不破不能立，不拆不成器，在拆书帮的大家庭，我将把知识拆为自己的能力，释放学习促进者的能量。\r\n【介绍拆书帮】自从加入拆书帮以后，经常会被问到拆书帮是什么？我会这样来回答：拆书帮是一个基于拆书法的学习爱好者社群，在全国各地设有拆书帮分舵，拆书帮分舵是公益性的青年自组织，其使命是帮助更多的学习爱好者成长为拆书家。\r\n拆书的“拆”不是“拆散”，而是转化和内化。“拆书”，就是强调把书本知识转化为学习者的能力。在这里，运用的拆书法称为RIA便签法。\r\nRIA便签具体包括R（阅读原文片段）、I（拆书家用自己的语言对片段进和重述和讲解）和A（拆为己用），运用RIA便签法，学习者不再停留在对书本阅读完就结束了，更强调的是与过往的经历相联系，并反思规划未来的运用，在反思转化为自己的能力的同时，促进他人的学习成长。","ratings_count":0,"texts":[{"id":6987,"quote":"\u003cp>“肯定的言辞”的表达方式之一，就是通过语言来表扬一个人，而表扬的焦点集中在他取得的成绩或成就上。当工作团队中有的人工作完成得非常好，达到甚至超过了我们的期望时，我们就会用到这种方式。这是吉姆最喜欢的方式，表扬会让他工作起来更有劲头。\u003c/p>\u003cp>在工作场合，这是很常见的赞赏方式。企业或团队存在的目的，就是为了完成某项使命。当团队的一员对这项使命做出卓越贡献时，得到表扬是很应该的。\u003c/p>\u003cp>这种方式的表扬通常集中在具体的事情上。“罗伯特，你今天上午的报告真是太棒了。我喜欢你引入国际化因素。我们需要在这方面多下工夫，谢谢你提醒了我。”\u003c/p>","explains":"\u003cp>在工作和生活中，当别人帮助了你或做了对你有利的事情、亦或是做了让你开心或欣赏的事情时，我们通常都会表扬对方来表达我们的肯定和赞赏之情。那么回想一下，在你表扬对方时，是不是千篇一律的只会用“谢谢”、“做得不错”、“你真棒”之类的词语，如果你的表扬方式如上所是都是泛泛而谈，那么你需要注意了，你的表扬方式的真实效果可能不尽如人意。\u003c/p>\u003cp>比如，当员工为团队做出了贡献或按照你喜欢的方式工作时，你泛泛的说一句“谢谢”或“做得不错”，这句表扬产生不了什么影响，员工感受不到你认可了他做的哪些具体的事情和贡献，如果你换成“做得不错，路还很长，继续加油”，不仅没有让对方感受到表扬可能还会让对方反感。所以，没有采取正确的表扬方式，不仅不能传达我们的肯定和赞赏、鼓励对方积极的行为，可能还会让对方产生负面的情绪。\u003c/p>\u003cp>那么如何表扬，才能更有效地让对方感受到我们的真诚，并起到激励的作用呢？首先，我们要明确表扬的核心要点是，表扬要具体。如何将表扬要具体落到实处呢？我们可以从以下两点入手：第一，对方做了什么事情，是我真正想要表扬他的。比如，原文中的具体事情就是“罗伯特，你今天上午的报告真是太棒了，我喜欢你引入国际化因素”。第二，这件事情带给我的好处或感受是什么样的。比如，原文中带来的“我们需要在这方面多下工夫，谢谢你提醒了我。”\u003c/p>","interaction":"\u003cp>A1：基于对原文片段的拆解，让我想到了最近一次我表扬失败的经历。上周末，我在外面做一场亲子教育的讲座，因为恰逢周末老公休息，于是老公和妈妈带着宝宝一起全家出动，我在活动场所做讲座的同时，他们带着宝宝在旁边的商场闲逛等我。中午讲座结束后，我到指定地点跟他们汇合时，看到老公买好了我爱吃的栗子，我很开心的接过栗子，说了声“哇，谢谢！”就开始吃了，我一边吃一边说“这个栗子挺好吃，就是凉了没有热的时候好吃”，我老公立马接着说“给你买就不错了，还挑三拣四的”，那一瞬间我的反应是我说错什么了吗？他是不是误会我的意思了？于是我赶紧说“我没别的意思啊，你给我买栗子我很开心啊，我一开始就表达感谢了啊”，老公说“下次不给你买了。”最后虽然他没有真的生气，但从他没有得到满足的表情可以看得出来对于我的反应他是有些小失落的，而我当时很不解的是自己明明是想表扬他的行为的，结果却事与愿违的搞砸了，自责的同时却没搞明白问题出在哪里，只能在郁闷中不了了之。\u003c/p>\u003cp>对照有效的表扬方式来看，我在对老公进行表扬时采取的方式简直太泛泛而谈了，不仅没有表达出我想表扬他的哪些具体行为，反而在中间还产生了误会，让表扬差点变成了指责，难怪最后以郁闷收场。\u003c/p>\u003cp>A2：现在再来反思自己表扬失败的经历，弄明白自己表扬方式的问题，在掌握了有效表扬的三步走方法后，我准备明天早上上班途中，跟他重提这件事。仔细一想，我想要表达肯定的具体事件不仅有买栗子，还有他愿意在休息日把全家的行程都根据我的行程来安排，支持我的事业发展。他给我买栗子让我很惊喜，觉得他逛街还想着买我爱吃的东西，他陪我出来让我很安心，感受到他的支持。最后，组织好话语真诚地表扬出来，我会对他说“老公，上周末我出去做讲座，谢谢你全程护送，带着全家一起出动支持我，让我感受到满满的支持和安心，更让我惊喜的事情是你还想着买了我爱吃的栗子，你简直太给力了，我上次没有告诉你，其实我看到栗子时是很感动和幸福的。”\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1510980821000,"updated_at":1510982236000,"ria":true},{"id":4017,"topic":"如何更好的赞赏人？","learn_goal":"学习更有效的赞赏别人","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"倪凌梅","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"大家晚上好，我是倪凌梅，我有3个标签，第1个标签：教育工作者；第2个标签：自由撰稿人；第3个标签：美食分享者；今天很高兴由我来给大家做TF1-2的拆书分享，学会如何赞赏。\r\n我们先进行小组分配，那我们根据座次3人一组，一会儿拆书的过程中需要小组讨论的时候请大家按照分配好的小组进行讨论。\r\n这本书是由一位著名的辅导专家盖瑞·查普曼博士写的，他曾写过《爱的5种语言》，非常畅销，而且很好用。《赞赏的5种语言》是《爱的五种语言》姊妹篇，通过学习书中的技巧，可以将它在实际生活和工作中进行运用和操练，慢慢养成赞赏别人的习惯，最终成为一个懂得赞赏的人。","ratings_count":0,"texts":[{"id":6970,"quote":"\u003cp>TF1-2&nbsp;《赞赏的5种语言》（盖瑞·查普曼/保罗·怀特 著）\u003c/p>\u003cp>“肯定的言辞”的表达方式之一，就是通过语言来表扬一个人，而表扬的焦点集中在他取得的成绩或成就上。当工作团队中有的人工作完成得非常好，达到甚至超过了我们的期望时，我们就会用到这种方式。这是吉姆最喜欢的方式，表扬会让他工作起来更有劲头。\u003c/p>\u003cp>在工作场合，这是很常见的赞赏方式。企业或团队存在的目的，就是为了完成某项使命。当团队的一员对这项使命做出卓越贡献时，得到表扬是很应该的。\u003c/p>\u003cp>这种方式的表扬通常集中在具体的事情上。“罗伯特，你今天上午的报告真是太棒了。我喜欢你引入国际化因素。我们需要在这方面多下工夫，谢谢你提醒了我。”\u003c/p>\u003cp>表扬越具体，效果越明显。当你看到某位志愿者或员工按照你喜欢的方式工作时，立刻给予表扬，他下一次会更有可能重复同样的行为。人类行为方式的研究印证了这种理论。“我喜欢你接电话时开心的语调，以及你主动为客户提供帮助。”你这样说，接待员下次还会这样做。说“谢谢你这么早就来做准备，让我们能够准时出发”，远比说“谢谢，你今天做得不错”要有意义得多。\u003c/p>\u003cp>事实证明，那种泛泛而谈的表扬，如“做得不错！”“你是个好学生！”基本上起不到鼓励的作用，也不能增加积极的行为，甚至会让人泄气。常有员工说：“我最讨厌老板说：‘大家做得不错！路还长呐！加油啊！’这哪是鼓励，简直就是诅咒。”再强调一遍：要让表扬有效，就必须具体。\u003cbr>\u003c/p>","explains":"\u003cp>今天分享的便签是：学会如何赞赏别人。\u003c/p>\u003cp>我们都喜欢得到别人的赞赏，同时我们也发现懂得赞赏别人的人能给别人带去激励，会让别人感到自己所创造的价值得到肯定，感到自己被关注被重视，也会给整个团队带来正能量。不论是在班级里、寝室里、家庭里、还是工作单位里，我们都需要懂得赞赏的人。\u003c/p>\u003cp>美国劳工部的一项调查显示：64%的人因在工作中得不到赏识而辞职，不管他是公司的CEO，还是普通的家政服务员，一概如此。人们在内心深处都渴望被赏识，这项需求得不到满足，工作满意度就会降低。\u003c/p>\u003cp>赞赏的第一种语言是肯定的言辞，那么在生活、工作中如何赞赏别人呢？我们可以这样做：\u003c/p>\u003cp>1、用肯定的语言；\u003c/p>\u003cp>2、赞赏的话体现在具体的事情上。\u003c/p>\u003cp>3、表扬的越具体，效果越明显。\u003c/p>\u003cp>比如，我家先生经常做晚饭，我原来经常这样赞赏他：“你做的饭真好吃。”但常常得不到他的回应。\u003c/p>\u003cp>自从看了《赞赏的五种语言》之后，我就改了话术，我会说：你做的每一道菜颜色都搭配得非常漂亮，总是特别注意颜色搭配，五彩缤纷，不仅好吃还好看，最喜欢吃你做的鱼香肉丝了；有时候还会自己看了菜谱进行思考改良，比如今天做的青椒海参真是美味，完全不输给大饭店。\u003c/p>\u003cp>然后，先生每次都喜滋滋的，有时候还会跟我和儿子探讨下菜式的做法，询问一下我和儿子，对他烧的菜有没有什么改进意见。\u003c/p>\u003cp>家庭氛围一下子就不一样了。由此可见，小小表扬，也是需要有技巧的，越具体越打动人。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>读完这个片段后，我们了解到“肯定的言辞”的表达方式，就是通过语言来表扬一个人，而表扬的焦点集中在他取得的成绩或成就上。\u003c/p>\u003cp>那么，请想一想过去我们是如何表扬我们家人、朋友、同事的，给大家2分钟写在便签纸上。写好的小组用3分钟时间在各自小组内分享，写好的请举手示意。举个例子：我是怎么夸另一半或孩子的。\u003c/p>\u003cp>好，现在开始……\u003c/p>\u003cp>好，现在请一位伙伴为大家分享她的便签。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>刘斐：原来觉得夫妻两个都要上班，老公做家务是应该的，都只会说：“谢谢的，谢谢啊。”改进后会说：你也蛮辛苦的，还给我倒水，谢谢啊。并在洗碗时偶尔关心一下，他在做家务时更加心甘情愿了。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>谢谢刚刚的小伙伴给我们分享他自己的案例，接下来的一周内，你将怎样用片段中的方法来表扬你的家人、朋友、同事等。\u003c/p>\u003cp>时间是1分钟，完成后请举手示意，现在开始……\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>贾文卿：女儿剪了头发，问我，怎么样啊。原来会夸她：漂亮的，青春美少女。现在呢，学了拆页后，第一，会更加具体一点，比如：有型的，更可爱了。第二，会立即夸奖，及时表扬，不能等到过期了就没劲了。\u003c/p>\u003cp>今天我的TF1-2分享到此结束，感谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1510659793000,"updated_at":1510660201000,"ria":true},{"id":1894,"topic":"如何赠送合适的物质性礼物 ","learn_goal":"学会如何送出符合对方喜好的物质性礼物","remark":"生活中赠送礼物是我们表达自己情感和表达尊重的一种方式，礼物的形式也是多种多样的，它可以是物质的，也可以是非物质的，物质，是指客观存在的一样东西。物质性礼物并不一定都是生活常见的各类商品，也许是一副涂鸦，或者一封信。每个人心里对于称心的礼物的需求也各有不同，本次的学习目标是：学会如何送出符合对方喜好的物质性礼物。","level":"TF1-2","duration":14,"status":0,"type":0,"chaishujia":{"username":"奔腾吧蜜蜂","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"分组：\r\n分成四个组 \r\n开场：\r\n大家好，我是刘馨裕，文刀刘，温馨的馨，富裕的裕。今天我的三个标签分别是：1、阅读爱好者，喜欢阅读，每次阅读的时侯也是感觉非常幸福的时侯。2、烹饪，一开始烹饪就是为了给爸妈做营养餐，再后来发现自己也挺喜欢吃的，所以，烹饪是我表达关心他人和爱自己的一种方式。3、家居创意爱好者，天生恋家，喜欢跟家居相关的一切创意。\r\n我今天申请的评级是TF1-2，将要为大家拆解的片段来自《赞赏的5种语言》。这是一本讲解通过不同赞赏方式去达到激励下属的目的的书，但赞赏不止适用于职场，更是日常生活中不可或缺的情感润滑剂。今天，我要为大家分享的是礼物赞赏法。现在，给大家2分钟时间阅读一下手中的片段。","ratings_count":0,"texts":[{"id":4499,"quote":"\u003cp>礼物的力量\u003c/p>\u003cp>对于喜欢接受礼物的人来说，一份称心如意的礼物能产生强大的力量，它不仅仅是一份礼物，更是一份感谢、赏识以及鼓励。对于不喜欢礼物的人来说，则起不了什么作用。要是送错了礼，还会招致反感。给正确的人送正确的东西，这的确难把握。\u003c/p>\u003cp>礼物：送给谁，送什么\u003c/p>\u003cp>要想让礼物起到鼓励的作用，要注意两个关键点：\u003c/p>\u003cp>\u003cstrong>第一，只给那些喜欢礼物的人送礼物。\u003c/strong>如果一个人对礼物不在意的话，你最好还是用他欣赏的主要赞赏语来表达对他的赞赏。人与人不同，有些人格外看重礼物，也有人对此不屑一顾。这里我们想再次强调：如果你想让人们感到被赏识，就要说他们的主要赞赏语。即使是赠送礼物，你也要注意，赠送的礼物要让他们觉得有意义。\u003c/p>\u003cp>例如圣诞节时，你给所有的员工买礼物，人手一份。有人非常高兴，有人反映平平，有些人甚至觉得礼物没用，扭头就给了别人。看到这一幕，你肯定觉得自己简直是在浪费时间和金钱。最好的办法是，送礼之前先了解一下，哪些人的主要或第二赞赏语是“称心的礼物”，然后再为他们选择合适的礼物。\u003c/p>\u003cp>\u003cstrong>第二，选择让对方觉得有价值的礼物。\u003c/strong>如果你送给某位男士两张芭蕾舞票，他不会觉得温暖又舒心。同样，单单想一想在寒冷的周日下午坐在球场上看职业橄榄球赛，女士们就会觉得浑身发冷。如果你把芭蕾舞演出门票给某位喜欢芭蕾舞的员工，这会让他们难以忘怀。橄榄球票也是同样道理。如果你是管理者，可能会说：“这难度也太大了，我可不想把时间浪费在送礼上。干脆什么都不送。”这种想法可以理解，但这种一刀切的处理方式，会让很多喜欢礼物的人感觉不到被欣赏。\u003c/p>\u003cp>那些不懂得赠送礼物技巧精神的人，送礼物经常送不到人们的心坎上。赠送礼物的关键不在于礼物，而在于通过礼物传递的心意，让对方看到我们花费了时间和精力，以此表达对他们的重视和赏识。在选择礼物前，要多想一想：“这个人喜欢什么？他的兴趣是什么？什么东西让他觉得自己很特别、被重视？”\u003c/p>","explains":"\u003cp>生活中赠送礼物是我们表达自己情感和表达尊重的一种方式，礼物的形式也是多种多样的，它可以是物质的，也可以是非物质的，物质，是指客观存在的一样东西。物质性礼物并不一定都是生活常见的各类商品，也许是一副涂鸦，或者一封信。每个人心里对于称心的礼物的需求也各有不同，今天要为大家分享如何赠送符合对方喜好的物质性礼物。接下来，我所说的礼物都是指物质性礼物，它有两个关键点：\u003c/p>\u003cp>1、给喜欢接受物质性礼物的人赠送礼物。\u003c/p>\u003cp>有些人的需要的可能是陪伴和交流，这时侯送再多的礼物，可能也不会是对方符合对方喜好的称心的礼物。\u003c/p>\u003cp>2、选择符合对方喜好的礼物。\u003c/p>\u003cp>在选择礼物之前，多想想，这个人喜欢什么？他的兴趣是什么？也可以在平时就注意观察，或者，直接询问对方喜欢什么。\u003c/p>\u003cp>我在14岁的时侯第一次送礼物给妈妈，那时侯刚知道康乃馨是代表母爱，于是送了一束康乃馨给妈妈，可我妈的第一反应是：你买这花干什么，长得真难看。当时觉得特别难过，因为很用心呀，花的自己的零花钱呀，可是看了这本书以后知道，我送的花并不符合我妈的喜好，她喜欢的是菊花，色彩艳丽的那种。那如果新年回去以后，我要给我妈再挑一份礼物，我会先跟她聊天，观察她最近关注的最多的是什么，提的多的是什么，我带她出去溜达，看她关注的是什么，根据这个去选择一份礼物给她。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1\u003c/strong>\u003cstrong>激活经验 \u003c/strong>\u003c/p>\u003cp>现在，请大家回想一下，在过去有没有遇到过这种情况：自己精心挑选的礼物被漠视，对方觉得莫名其妙，你觉得很委屈，请大家在小组内讨论一下，给大家三分钟时间。\u003c/p>\u003cp>\u003cstrong>学习者1\u003c/strong>：\u003c/p>\u003cp>我有一个失败的案例，我觉得我从来没给我弟买什么特别的东西，然后我就想到不能送太平凡的，太普通的礼物，想送一点有价值，有意义的礼物给他，就想到送块玉给他，希望给他带来好运呀什么的，别人说玉养人嘛，我就刻意的去挑了一块玉给他，结果他说：“你这是干嘛呀，这简直是浪费钱，你还不如给我钱，我又不喜欢戴这种东西。”然后我就说：“这个对你好呀，能给你带来好运呀，养身体呀。”我说了好久，他勉强戴上了，过了段时间又说：“哎呀，这戴着不舒服呀，别扭呀。”然后就拿下来了，一直放在那里，我1千多块钱就白花了，就感觉特别心塞。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003cstrong>催化应用\u003c/strong>\u003c/p>\u003cp>今天，我们学习了这个片段，知道选择礼物，第一，要给喜欢接受礼物的人赠送礼物，这边说的是物质性礼物。第二、要选择符合对方喜好的礼物。这个喜好呢，可以根据我们平时对对方的观察，甚至是可以直接去询问：你喜欢什么呀？我准备送个什么给你呀…马上就要跨年了，如果送一份礼物给自己今年特别感激的人，根据今天所学，在12月31号之前为对方准备一份跨年礼，你打算选择一份怎样的礼物送给对方，原因又是什么呢？请大家在便签上写下来。\u003c/p>\u003cp>我看到绝大部分小伙伴都写出来了，那么现在我想请一位小伙伴分享一下他的便签，好，娟元。\u003c/p>\u003cp>学习者1：\u003c/p>\u003cp>我觉得我今年最感激的人是我自己，因为我突破了很多的困难，做到了很多我以前不能做到的事，所以，我想送我自己一套衣服。是我最喜欢的，以前挺舍不得买的。\u003c/p>\u003cp>拆书家：好棒呀，我好期待看到你的新衣服。\u003c/p>\u003cp>那么由于时间的关系，就请这一位小伙伴分享了，今天我的分享就到这里了，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1485252082000,"updated_at":1485252082000,"ria":true},{"id":7,"topic":"便签读书法练习","learn_goal":"掌握便签读书法","remark":"","level":"TF1-1","duration":5,"status":0,"type":0,"chaishujia":{"username":"拆书帮小师妹","city":""},"club":{"name":"筹备分舵","city":"北京市"},"prologue":null,"ratings_count":0,"texts":[{"id":14,"quote":"表扬越具体，效果越明显。当你看到某位志愿者或员工按照你喜欢的方式工作时，李可给予表扬，他下一次会更有可能重复同样的行为。人类行为方式的研究印证了这种理论。“我喜欢你接电话时开心的语调，以及你主动为客户提供帮助。”你这样说，接待员下次还会这样做。说“谢谢你这么早就来做准备，让我们能够准时出发”，远比“谢谢，你今天做的不错”要有意义得多。","explains":"表扬越是具体效果越明显。\r\n感谢也是一样，越具体越容易被对方接收到。\r\n具体而明确的肯定，更能使对方内心感受到你真的在欣赏和称赞他。\r\n他会更有信心和动力继续去做，并且做得更好。","interaction":"A1：描述自己的相关经验\r\n上周末，几个朋友一起聊天，我谈到了1.0和2.0的不同，传统传播方式与交互式传播的不同，以及微信的营销与品牌推广等等。一位朋友说：“挺好的！”另一位朋友说：“听你讲这些，我觉得挺有意思，我之前没有想过这些，挺让我开阔思路的。”很显然，听了第二位朋友的话，我觉得更受用，我会愿意在和他进一步的聊天和探讨。\r\nA2：以后我怎么用\r\n在两周之内，我会对至少一个人（同事、家人或者朋友），做一次具体的表扬或称赞，要让对方明确的感受得到我对他（她）的欣赏。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1446885773000,"updated_at":1446885773000,"ria":true}]};